exec(compile('#!/usr/bin/env python3\n"""EVA R8 guarded one-shot verified football-paper settlement.\n\nStrict two-source score consensus and exact original historical quote only.\nNo code/services touched; sqlite online backup + atomic conditional updates.\nR8 aborts closed if any source, quote, schema, identity, or live-state guard fails.\n"""\nimport contextlib\nimport datetime as dt\nimport hashlib\nimport io\nimport json\nimport math\nimport os\nfrom pathlib import Path\nimport shutil\nimport sqlite3\nimport sys\nimport time\nimport uuid\n\nimport types\na=types.ModuleType(\'eva_r8_bundled_audit\')\nexec(compile(\'#!/usr/bin/env python3\\n"""R7.3 independent second gate. Never calls setup/settle or mutates SQLite.\\n\\nUsed exclusively after R7.2\\\'s strict provider+identity+timestamp gate.\\n"""\\nimport collections\\nimport datetime as dt\\nimport importlib\\nimport json\\nimport math\\nimport sys\\nfrom dataclasses import dataclass\\n\\nREQUIRED_PAPER={\\n    \\\'forecast_id\\\',\\\'original_event_id\\\',\\\'origin\\\',\\\'status\\\',\\\'kickoff_utc\\\',\\\'quote_at\\\',\\n    \\\'registered_at\\\',\\\'odds\\\',\\\'stake\\\',\\\'quote_key\\\',\\\'market\\\',\\\'selection\\\',\\\'root_id\\\',\\n    \\\'result_home\\\',\\\'result_away\\\'}\\nREQUIRED_PARENT={\\\'id\\\',\\\'root_id\\\',\\\'created_at\\\',\\\'kickoff_utc\\\',\\\'market\\\',\\\'selection\\\'}\\nREQUIRED_HIST={\\\'quote_key\\\',\\\'decimal_price\\\',\\\'changed_at\\\'}\\nREQUIRED_CURRENT={\\\'quote_key\\\',\\\'root_event_id\\\',\\\'event_id\\\',\\\'factor_id\\\',\\\'point\\\'}\\n\\n\\ndef columns(db, name):\\n    return {r[1] for r in db.execute(\\\'PRAGMA table_info(\\\'+name+\\\')\\\')}\\n\\n\\ndef clock(v):\\n    try:\\n        d=dt.datetime.fromisoformat(str(v).replace(\\\'Z\\\',\\\'+00:00\\\'))\\n        if d.tzinfo is not None:return d.astimezone(dt.timezone.utc)\\n    except (TypeError,ValueError,OverflowError):pass\\n    return None\\n\\n\\ndef quote_semantics(v5, market,selection,fac,point):\\n    """Native forecast canonical == provider\\\'s documented FT factor semantic."""\\n    try:\\n        canonical=v5.canonical_selection(market,selection)\\n        if canonical is None:return False\\n        key=str(fac)\\n        if key in v5.KNOWN_FT_1X2:\\n            expected=(\\\'1X2\\\',v5.KNOWN_FT_1X2[key])\\n        elif key in v5.KNOWN_DC:\\n            expected=(\\\'DOUBLE_CHANCE\\\',v5.KNOWN_DC[key])\\n        elif key in v5.KNOWN_BTTS:\\n            expected=(\\\'BTTS\\\',v5.KNOWN_BTTS[key])\\n        elif key in v5.KNOWN_TOTAL:\\n            line=v5.total_line(point)\\n            if line is None:return False\\n            expected=(\\\'TOTAL\\\',v5.KNOWN_TOTAL[key],line)\\n        else:return False\\n        if canonical!=expected:return False\\n        if expected[0]!=\\\'TOTAL\\\':\\n            obj=json.loads(point or \\\'{}\\\')\\n            if not isinstance(obj,dict) or obj.get(\\\'p\\\') is not None or obj.get(\\\'pt\\\') is not None:return False\\n        return True\\n    except (ValueError,TypeError,AttributeError,KeyError,OverflowError):return False\\n\\n\\nclass Preview:\\n    def __init__(self,db):\\n        self.db=db\\n        self.reasons=collections.Counter()\\n        self.outcomes=collections.Counter()\\n        self.leagues=collections.Counter()\\n        self.stake=0.0\\n        self.profit=0.0\\n        self.examples=[]\\n        self.events=set()\\n        self.candidates=0\\n        self.v5=None\\n        self.settlement=None\\n        self.missing=[]\\n        self.price_gap=collections.Counter()\\n        self.price_gap_leagues=collections.defaultdict(collections.Counter)\\n        self.price_gap_examples=[]\\n        self.price_gap_keys=set()\\n        self.price_gap_count=0\\n        self.gap_rows=[]\\n        for name,needed in [(\\\'v55_paper\\\',REQUIRED_PAPER),(\\\'v5_forecasts\\\',REQUIRED_PARENT),\\n                            (\\\'fb_full_history\\\',REQUIRED_HIST),(\\\'fb_full_current\\\',REQUIRED_CURRENT)]:\\n            missed=sorted(needed-columns(db,name))\\n            if missed:self.missing.append(name+\\\':\\\'+\\\',\\\'.join(missed))\\n        # Freeze native outcome and market semantics to the R5 audited source code.\\n        # On synthetic local tests /app is not mounted, so mocked modules are used.\\n        verified_sources={\\n          \\\'/app/oracle_v5.py\\\':\\\'b243e223efdbe48b931dfa26bec729261885dbd0ca87a8ea07c24e5418d6ae1c\\\',\\n          \\\'/app/oracle_v5_settlement.py\\\':\\\'a22936af760b26e0cbed3eacdea5f3a6ade0f757e4297caf6a881a3dca3ecf2f\\\'\\n        }\\n        if __import__(\\\'pathlib\\\').Path(\\\'/app\\\').is_dir():\\n            import hashlib\\n            for fname,expected_sha in verified_sources.items():\\n                try:\\n                    with open(fname,\\\'rb\\\') as inp:\\n                        dig=hashlib.sha256()\\n                        for part in iter(lambda:inp.read(262144),b\\\'\\\'):dig.update(part)\\n                    if dig.hexdigest()!=expected_sha:self.missing.append(\\\'UNAUDITED_NATIVE_SOURCE_SHA:\\\'+fname)\\n                except OSError:self.missing.append(\\\'NATIVE_SOURCE_MISSING:\\\'+fname)\\n        if not self.missing:\\n            try:\\n                sys.path.insert(0,\\\'/app\\\') if \\\'/app\\\' not in sys.path else None\\n                self.v5=importlib.import_module(\\\'oracle_v5\\\')\\n                self.settlement=importlib.import_module(\\\'oracle_v5_settlement\\\')\\n                if not callable(getattr(self.settlement,\\\'_market_outcome\\\',None)):\\n                    self.missing.append(\\\'native_market_outcome_missing\\\')\\n            except Exception as exc:self.missing.append(\\\'native_import:\\\'+type(exc).__name__)\\n\\n    def _diagnose_gap(self, qkey, qat, odds, league, fid=None, registered_at=None):\\n        "Forensic characterization only. Never converts a missing observation into a price."\\n        from hashlib import sha256\\n        self.price_gap_count+=1\\n        self.price_gap_keys.add(qkey)\\n        self.gap_rows.append({\\\'qkey\\\':qkey,\\\'qat\\\':qat,\\\'odds\\\':odds,\\\'league\\\':league,\\\'fid\\\':fid,\\\'registered_at\\\':registered_at})\\n        q=clock(qat)\\n        try:\\n            # Available history range for the exact immutable quote identity.\\n            bounds=self.db.execute(\\\'\\\'\\\'SELECT COUNT(*),MIN(changed_at),MAX(changed_at)\\n                FROM fb_full_history WHERE quote_key=?\\\'\\\'\\\',(qkey,)).fetchone()\\n            n=int(bounds[0])\\n            if n==0:\\n                existing=self.db.execute(\\\'\\\'\\\'SELECT COUNT(*) FROM fb_full_current\\n                    WHERE quote_key=?\\\'\\\'\\\',(qkey,)).fetchone()[0]\\n                category=(\\\'NO_HISTORY_KEY_CURRENT_EXISTS\\\' if existing\\n                          else \\\'NO_HISTORY_KEY_AND_NO_CURRENT\\\')\\n                past=future=None\\n            else:\\n                past=self.db.execute(\\\'\\\'\\\'SELECT decimal_price,changed_at\\n                    FROM fb_full_history WHERE quote_key=? AND changed_at<=?\\n                    ORDER BY changed_at DESC LIMIT 1\\\'\\\'\\\',(qkey,qat)).fetchone()\\n                future=self.db.execute(\\\'\\\'\\\'SELECT decimal_price,changed_at\\n                    FROM fb_full_history WHERE quote_key=? AND changed_at>?\\n                    ORDER BY changed_at ASC LIMIT 1\\\'\\\'\\\',(qkey,qat)).fetchone()\\n                if not q:\\n                    category=\\\'MALFORMED_QUOTE_AT\\\'\\n                elif past and clock(past[1]) == q:\\n                    category=\\\'SAME_INSTANT_DIFFERENT_TIMESTAMP_FORMAT\\\'\\n                elif past and isinstance(past[0],(float,int)) and abs(past[0]-float(odds)) <= 1e-6:\\n                    category=(\\\'PRIOR_PRICE_MATCH_BOUNDED_BY_NEXT_CHANGE\\\' if future\\n                              else \\\'PRIOR_PRICE_MATCH_NO_NEXT_CHANGE\\\')\\n                elif past:\\n                    category=\\\'PRIOR_PRICE_DIFFERENT\\\'\\n                elif future:\\n                    category=\\\'ONLY_FUTURE_PRICE_HISTORY\\\'\\n                else:\\n                    category=\\\'QUOTE_KEY_HISTORY_NO_ORDERABLE_TIMES\\\'\\n            self.price_gap[category]+=1\\n            self.price_gap_leagues[str(league)][category]+=1\\n            if len(self.price_gap_examples)<12:\\n                self.price_gap_examples.append({\\n                    \\\'quote_sha8\\\':sha256(str(qkey).encode()).hexdigest()[:8],\\n                    \\\'league\\\':league,\\\'reason\\\':category,\\n                    \\\'history_rows_for_key\\\':n,\\n                    \\\'quote_at\\\':str(qat),\\n                    \\\'prior_at\\\':past[1] if past else None,\\n                    \\\'next_at\\\':future[1] if future else None,\\n                    \\\'price_matches_prior\\\':bool(past and isinstance(past[0],(float,int)) and abs(past[0]-float(odds))<=1e-6),\\n                })\\n        except Exception as exc:\\n            self.price_gap[\\\'DIAGNOSTIC_QUERY_ERROR_\\\'+type(exc).__name__]+=1\\n            self.price_gap_leagues[str(league)][\\\'DIAGNOSTIC_QUERY_ERROR_\\\'+type(exc).__name__]+=1\\n\\n    def diagnostic_report(self):\\n        data={\\n            \\\'diagnosed_missing_price_observations\\\':self.price_gap_count,\\n            \\\'distinct_missing_quote_keys\\\':len(self.price_gap_keys),\\n            \\\'diagnostic_categories\\\':dict(self.price_gap),\\n            \\\'by_league\\\':{k:dict(v) for k,v in sorted(self.price_gap_leagues.items())},\\n            \\\'examples_sha8\\\':self.price_gap_examples,\\n            \\\'interpretation\\\':\\\'A prior matching price does NOT prove a snapshot was observed at quote_at. No failed candidate was promoted.\\\',\\n            \\\'db_writes\\\':0,\\\'real_orders\\\':0\\n        }\\n        print(\\\'R7_4_PRICE_GAP_FORENSICS\\\',json.dumps(data,ensure_ascii=False,sort_keys=True),flush=True)\\n        return data\\n\\n\\n    def capture_provenance_report(self):\\n        """Forensic audit of snapshot metadata only. NO candidate promotions or changes."""\\n        import bisect, hashlib, pathlib, ast, statistics\\n        db=self.db\\n        rows=self.gap_rows\\n        digest=lambda s:hashlib.sha256(str(s).encode(\\\'utf-8\\\')).hexdigest()[:8]\\n        def stamp(value):\\n            v=clock(value)\\n            if v is not None:return v\\n            if isinstance(value,(int,float)) and 946684800<=float(value)<=4102444800:\\n                return dt.datetime.fromtimestamp(float(value),dt.timezone.utc)\\n            return None\\n        def table_exists(name):\\n            return db.execute("SELECT 1 FROM sqlite_master WHERE type=\\\'table\\\' AND name=?",(name,)).fetchone() is not None\\n        def bounded_times(name):\\n            """Global ingestion runs/packets. DO NOT infer quote-level presence."""\\n            if not table_exists(name):return {\\\'status\\\':\\\'TABLE_NOT_FOUND\\\',\\\'timestamp_column\\\':None,\\\'sampled_rows\\\':0,\\\'timestamps\\\':[]}\\n            meta=db.execute(\\\'PRAGMA table_info(\\\'+name+\\\')\\\').fetchall()\\n            cols=[c[1] for c in meta]\\n            preferred=((\\\'imported_at\\\',) if name==\\\'fb_full_packets\\\' else (\\\'checked_at\\\',) if name==\\\'fb_full_runs\\\' else ()) + (\\n                       \\\'at\\\',\\\'received_at\\\',\\\'observed_at\\\',\\\'fetched_at\\\',\\\'snapshot_at\\\',\\\'captured_at\\\',\\n                       \\\'created_at\\\',\\\'run_at\\\',\\\'started_at\\\',\\\'completed_at\\\',\\\'timestamp_utc\\\',\\\'timestamp\\\')\\n            col=next((x for x in preferred if x in cols),None)\\n            result={\\\'status\\\':\\\'OK\\\' if col else \\\'NO_RECOGNIZED_TIMESTAMP_COLUMN\\\',\\n                    \\\'timestamp_column\\\':col,\\\'schema_columns\\\':cols[:35],\\\'sampled_rows\\\':0,\\n                    \\\'scan_truncated\\\':False,\\\'timestamps\\\':[]}\\n            if not col:return result\\n            # Both table & column are from hardcoded allowed names/PRAGMA, not user input.\\n            # Deterministic chronological scan (not arbitrary table insertion order).\\n            # The cap is conservative; INCOMPLETE_SCAN means unknown, not absent.\\n            raw=db.execute(\\\'SELECT "\\\'+col+\\\'" FROM "\\\'+name+\\\'" ORDER BY "\\\'+col+\\\'" LIMIT 50001\\\').fetchall()\\n            result[\\\'sampled_rows\\\']=min(len(raw),50000)\\n            result[\\\'scan_truncated\\\']=len(raw)>50000\\n            result[\\\'scan_order\\\']=\\\'timestamp_ascending_lexical\\\'\\n            result[\\\'coverage_note\\\']=\\\'If truncated or non-ISO timestamps, lack of a nearby packet is inconclusive\\\'\\n            if result[\\\'scan_truncated\\\']:\\n                # A truncated scan must never imply absence of coverage.\\n                result[\\\'status\\\']=\\\'INCOMPLETE_SCAN\\\'\\n            ticks=sorted(set(int(t.timestamp()) for (v,) in raw[:50000] if (t:=stamp(v)) is not None))\\n            result[\\\'timestamps\\\']=ticks\\n            result[\\\'parsed_times\\\']=len(ticks)\\n            return result\\n        def nearest(ticks, q):\\n            if q is None or not ticks:return None\\n            i=bisect.bisect_left(ticks,q)\\n            before=ticks[i-1] if i>0 else None\\n            after=ticks[i] if i<len(ticks) else None\\n            # Return distance to closest observed global-ingest timestamp.\\n            candidates=[abs(x-q) for x in (before,after) if x is not None]\\n            return min(candidates) if candidates else None\\n        source={\\\'status\\\':\\\'UNKNOWN\\\',\\\'prepare_found\\\':False}\\n        module=pathlib.Path(\\\'/app/oracle_v5_settlement.py\\\')\\n        try:\\n            code=module.read_bytes()\\n            tree=ast.parse(code,filename=str(module))\\n            fn=next((x for x in tree.body if isinstance(x,(ast.FunctionDef,ast.AsyncFunctionDef)) and x.name==\\\'prepare\\\'),None)\\n            source={\\\'status\\\':\\\'PARSED\\\' if fn else \\\'PREPARE_NOT_FOUND\\\',\\n                    \\\'source_sha256\\\':hashlib.sha256(code).hexdigest(),\\n                    \\\'prepare_found\\\':fn is not None}\\n            if fn:\\n                segment=ast.get_source_segment(code.decode(\\\'utf-8\\\'),fn) or \\\'\\\'\\n                source[\\\'prepare_references\\\']={x:(x in segment) for x in\\n                    (\\\'v5_forecasts\\\',\\\'quote_snapshot\\\',\\\'fb_full_history\\\',\\\'changed_at\\\',\\\'fb_full_packets\\\',\\\'source_packet\\\',\\\'quote_at\\\',\\\'quote_key\\\')}\\n                source[\\\'prepare_start_line\\\']=fn.lineno\\n        except (OSError,SyntaxError,UnicodeError) as exc:\\n            source={\\\'status\\\':\\\'CANNOT_PARSE_SOURCE\\\',\\\'error_type\\\':type(exc).__name__,\\\'prepare_found\\\':False}\\n        packet=bounded_times(\\\'fb_full_packets\\\')\\n        runs=bounded_times(\\\'fb_full_runs\\\')\\n        has_parent=table_exists(\\\'v5_forecasts\\\') and \\\'quote_snapshot\\\' in columns(db,\\\'v5_forecasts\\\')\\n        has_price=table_exists(\\\'v5_forecasts\\\') and \\\'price\\\' in columns(db,\\\'v5_forecasts\\\')\\n        has_pkey=table_exists(\\\'v5_forecasts\\\') and \\\'quote_key\\\' in columns(db,\\\'v5_forecasts\\\')\\n        parent_matches=0;parent_seen=0;parent_price_matches=0;parent_key_matches=0\\n        parent_quote_mismatches=collections.Counter();parent_mismatch_examples=[];parent_snapshot_deltas=[]\\n        elapsed=[];gap_hours=[];counts=collections.Counter(); examples=[]\\n        global_exact=0; global_1m=0; global_10m=0\\n        parent_query=\\\'SELECT quote_snapshot\\\'+(\\\',price\\\' if has_price else \\\'\\\')+(\\\',quote_key\\\' if has_pkey else \\\'\\\')+\\\' FROM v5_forecasts WHERE id=?\\\'\\n        for x in rows:\\n            quote=stamp(x[\\\'qat\\\']);reg=stamp(x[\\\'registered_at\\\'])\\n            qtick=int(quote.timestamp()) if quote is not None else None\\n            if quote is None:\\n                counts[\\\'INVALID_QUOTE_AT\\\']+=1;continue\\n            if reg is not None:elapsed.append((reg-quote).total_seconds()/3600)\\n            prior=db.execute("""SELECT decimal_price,changed_at FROM fb_full_history\\n                WHERE quote_key=? AND changed_at<=? ORDER BY changed_at DESC LIMIT 1""",\\n                (x[\\\'qkey\\\'],x[\\\'qat\\\'])).fetchone()\\n            nextrow=db.execute("""SELECT decimal_price,changed_at FROM fb_full_history\\n                WHERE quote_key=? AND changed_at>? ORDER BY changed_at ASC LIMIT 1""",\\n                (x[\\\'qkey\\\'],x[\\\'qat\\\'])).fetchone()\\n            before=stamp(prior[1]) if prior else None; after=stamp(nextrow[1]) if nextrow else None\\n            if before:gap_hours.append((quote-before).total_seconds()/3600)\\n            if before and after and before<=quote<after and isinstance(prior[0],(float,int)) and abs(float(prior[0])-float(x[\\\'odds\\\']))<1e-6:\\n                counts[\\\'PRIOR_PRICE_VALUE_COVERED_BY_NEXT_CHANGE\\\']+=1\\n            else:counts[\\\'NOT_VALUE_BOUNDED\\\']+=1\\n            if has_parent and x[\\\'fid\\\']:\\n                parent=db.execute(parent_query,(x[\\\'fid\\\'],)).fetchone()\\n                if parent:\\n                    parent_seen+=1\\n                    parent_ts=stamp(parent[0])\\n                    snapshot_match=(parent_ts==quote)\\n                    parent_matches+=int(snapshot_match)\\n                    if not snapshot_match:\\n                        parent_quote_mismatches[\\\'PARENT_SNAPSHOT_TIME_DIFFERENT\\\']+=1\\n                        if parent_ts and quote:parent_snapshot_deltas.append((quote-parent_ts).total_seconds()/3600)\\n                    idx=1\\n                    price_match=True\\n                    if has_price:\\n                        try:price_match=bool(parent[idx] is not None and abs(float(parent[idx])-float(x[\\\'odds\\\']))<1e-6)\\n                        except (ValueError,TypeError,OverflowError):price_match=False\\n                        parent_price_matches+=int(price_match)\\n                        if not price_match:parent_quote_mismatches[\\\'PARENT_PRICE_DIFFERENT\\\']+=1\\n                        idx+=1\\n                    key_match=True\\n                    if has_pkey:\\n                        key_match=(str(parent[idx])==str(x[\\\'qkey\\\']))\\n                        parent_key_matches+=int(key_match)\\n                        if not key_match:parent_quote_mismatches[\\\'PARENT_KEY_DIFFERENT\\\']+=1\\n                    if (not snapshot_match or not price_match or not key_match) and len(parent_mismatch_examples)<16:\\n                        parent_mismatch_examples.append({\\\'forecast_sha8\\\':digest(x[\\\'fid\\\']),\\n                            \\\'quote_sha8\\\':digest(x[\\\'qkey\\\']), \\\'league\\\':x[\\\'league\\\'],\\n                            \\\'snapshot_matches\\\':snapshot_match,\\\'price_matches\\\':price_match,\\n                            \\\'key_matches\\\':key_match,\\n                            \\\'snapshot_delta_hours\\\':round((quote-parent_ts).total_seconds()/3600,4) if parent_ts and quote else None})\\n            p=nearest(packet[\\\'timestamps\\\'],qtick)\\n            r=nearest(runs[\\\'timestamps\\\'],qtick)\\n            if p==0:global_exact+=1\\n            if p is not None and p<=60:global_1m+=1\\n            if p is not None and p<=600:global_10m+=1\\n            counts[\\\'GLOBAL_PACKET_WITHIN_60S\\\' if p is not None and p<=60 else\\n                   \\\'GLOBAL_PACKET_WITHIN_10MIN\\\' if p is not None and p<=600 else\\n                   \\\'GLOBAL_PACKET_NOT_NEAR_OR_UNKNOWN\\\']+=1\\n            if len(examples)<12:\\n                examples.append({\\\'forecast_sha8\\\':digest(x[\\\'fid\\\']),\\n                                 \\\'quote_sha8\\\':digest(x[\\\'qkey\\\']),\\n                                 \\\'quote_at\\\':x[\\\'qat\\\'], \\\'league\\\':x[\\\'league\\\'],\\n                                 \\\'last_change_hours_before\\\':round((quote-before).total_seconds()/3600,2) if before else None,\\n                                 \\\'next_change_hours_after\\\':round((after-quote).total_seconds()/3600,2) if after else None,\\n                                 \\\'nearest_global_packet_sec\\\':p,\\n                                 \\\'nearest_global_run_sec\\\':r})\\n        def summary(x):\\n            if not x:return None\\n            s=sorted(x)\\n            return {\\\'min\\\':round(s[0],2),\\\'median\\\':round(statistics.median(s),2),\\\'p90\\\':round(s[min(len(s)-1,int(.9*(len(s)-1)))],2),\\\'max\\\':round(s[-1],2)}\\n        def clean(m):\\n            return {k:v for k,v in m.items() if k!=\\\'timestamps\\\'}\\n        report={\\\'scope\\\':\\\'R7_4_NO_ORIGINAL_PRICE_OBSERVATION_ONLY\\\',\\n                \\\'missing_price_bets\\\':len(rows),\\n                \\\'distinct_missing_quote_keys\\\':len({x[\\\'qkey\\\'] for x in rows}),\\n                \\\'source_code\\\':source,\\n                \\\'r7_6_version\\\':\\\'R7.6_TIMESTAMP_COLUMN_REPAIR\\\',\\n                \\\'parent_forecast_quote_snapshot_column\\\':has_parent,\\n                \\\'parent_rows_present\\\':parent_seen,\\n                \\\'quote_at_equals_parent_quote_snapshot\\\':parent_matches,\\n                \\\'paper_odds_equals_parent_price\\\':parent_price_matches if has_price else None,\\n                \\\'paper_quote_key_equals_parent_key\\\':parent_key_matches if has_pkey else None,\\n                \\\'r7_6_parent_discrepancies\\\':dict(parent_quote_mismatches),\\n                \\\'r7_6_parent_examples_sha8\\\':parent_mismatch_examples,\\n                \\\'r7_6_snapshot_delta_hours\\\':summary(parent_snapshot_deltas),\\n                \\\'r7_6_metadata_note\\\':\\\'imported_at/checked_at are global ingestion timestamps, NOT quote-specific observation evidence\\\',\\n                \\\'quote_to_registration_hours\\\':summary(elapsed),\\n                \\\'last_price_change_age_hours\\\':summary(gap_hours),\\n                \\\'metadata_packet\\\':clean(packet),\\\'metadata_runs\\\':clean(runs),\\n                \\\'packet_exact_second_matches\\\':global_exact,\\n                \\\'packet_within_60s\\\':global_1m,\\\'packet_within_10min\\\':global_10m,\\n                \\\'packet_within_60s_not_quote_level_evidence\\\':True,\\n                \\\'diagnostics\\\':dict(counts), \\\'examples_sha8\\\':examples,\\n                \\\'errors\\\':[],\\n                \\\'interpretation\\\':\\\'Global packet/run metadata and price intervals are NOT proof of quote-level observation at quote_at. No candidates promoted.\\\',\\n                \\\'db_writes\\\':0,\\\'real_orders\\\':0}\\n        print(\\\'R7_5_CAPTURE_PROVENANCE\\\',json.dumps(report,ensure_ascii=False,sort_keys=True),flush=True)\\n        return report\\n\\n    def reason(self, name):self.reasons[name]+=1\\n\\n    def check(self, t, espn, csv, gate_counts, gate_total,now):\\n        """Count one and only one outcome per eligible PENDING forecast."""\\n        if gate_total<=0 or gate_counts.get(\\\'STRICT_ELIGIBLE\\\',0)!=gate_total:\\n            return\\n        rows=self.db.execute(\\\'\\\'\\\'SELECT forecast_id,root_id,market,selection,odds,stake,\\n               quote_key,quote_at,registered_at,kickoff_utc\\n             FROM v55_paper WHERE origin=\\\'sf_forecasts\\\' AND original_event_id=? AND status=\\\'PENDING\\\' \\\'\\\'\\\',\\n             (t[\\\'id\\\'],)).fetchall() if not self.missing else []\\n        if self.missing:\\n            for _ in range(gate_total):self.reason(\\\'MISSING_SCHEMA_OR_NATIVE_CODE\\\')\\n            return\\n        if len(rows)!=gate_total:\\n            for _ in range(gate_total):self.reason(\\\'LIVE_SNAPSHOT_COUNT_CHANGED\\\')\\n            return\\n        if len({x[0] for x in rows})!=len(rows):\\n            for _ in rows:self.reason(\\\'DUPLICATE_FORECAST_ID\\\')\\n            return\\n        for fid,root,market,selection,odds,stake,qkey,qat,registered,kick in rows:\\n            self.current_league=t[\\\'league\\\']\\n            self.candidates+=1\\n            s=self._check_one(fid,root,market,selection,odds,stake,qkey,qat,registered,kick,t,espn)\\n            if s[0]!=\\\'OK\\\':\\n                self.reason(s[0]);continue\\n            state,profit=s[1:]\\n            self.outcomes[state]+=1\\n            self.leagues[t[\\\'league\\\']]+=1\\n            self.stake+=float(stake)\\n            self.profit+=profit\\n            self.events.add(t[\\\'id\\\'])\\n            if len(self.examples)<10:self.examples.append({\\\'forecast_id_sha8\\\':__import__(\\\'hashlib\\\').sha256(str(fid).encode()).hexdigest()[:8],\\n                \\\'league\\\':t[\\\'league\\\'],\\\'status\\\':state,\\\'profit\\\':round(profit,4)})\\n\\n    def _check_one(self,fid,root,market,selection,odds,stake,qkey,qat,registered,kick,t,espn):\\n        k,q,r=clock(kick),clock(qat),clock(registered)\\n        if not k or not q or not r or not q<r<k:\\n            return (\\\'REGISTRATION_OR_QUOTE_ORDER_INVALID\\\',)\\n        if not root or not qkey or not isinstance(odds,(float,int)) or not math.isfinite(odds) or not 1.001<odds<=1001:\\n            return (\\\'INVALID_QUOTE_OR_ODDS\\\',)\\n        if not isinstance(stake,(float,int)) or not math.isfinite(stake) or not 0<stake<=10000:\\n            return (\\\'INVALID_STAKE\\\',)\\n        parent=self.db.execute(\\\'\\\'\\\'SELECT root_id,created_at,kickoff_utc,market,selection\\n            FROM v5_forecasts WHERE id=?\\\'\\\'\\\',(fid,)).fetchall()\\n        if len(parent)!=1:return (\\\'PARENT_FORECAST_NOT_UNIQUE\\\',)\\n        p_root,created,p_kick,p_market,p_sel=parent[0]\\n        pc,pk=clock(created),clock(p_kick)\\n        if p_root!=root or pc is None or pk is None or pc>q or abs((pk-k).total_seconds())>600:\\n            return (\\\'PARENT_FORECAST_IDENTITY_OR_TIME\\\',)\\n        try:\\n            if self.v5.canonical_selection(p_market,p_sel)!=self.v5.canonical_selection(market,selection):\\n                return (\\\'PARENT_SELECTION_MISMATCH\\\',)\\n        except Exception:return (\\\'PARENT_SELECTION_PARSE_ERROR\\\',)\\n        # A quote must be uniquely identifiable in the ORIGINAL captured odds\\n        # history; a convenient current quote is NOT proof of the old price.\\n        hist=self.db.execute(\\\'\\\'\\\'SELECT decimal_price,changed_at FROM fb_full_history\\n                    WHERE quote_key=? AND changed_at=? LIMIT 3\\\'\\\'\\\',(qkey,qat)).fetchall()\\n        if not hist:\\n            self._diagnose_gap(qkey,qat,odds,self.current_league,fid,registered)\\n            return (\\\'NO_ORIGINAL_PRICE_OBSERVATION\\\',)\\n        if len(hist)>1:return (\\\'DUPLICATE_PRICE_HISTORY\\\',)\\n        price,observed=hist[0]\\n        if not isinstance(price,(float,int)) or not math.isfinite(price) or abs(float(price)-float(odds))>0.000001:\\n            return (\\\'ORIGINAL_ODDS_MISMATCH\\\',)\\n        if clock(observed)!=q:return (\\\'ORIGINAL_QUOTE_TIME_MISMATCH\\\',)\\n        mapping=self.db.execute(\\\'\\\'\\\'SELECT root_event_id,event_id,factor_id,point\\n                   FROM fb_full_current WHERE quote_key=? LIMIT 3\\\'\\\'\\\',(qkey,)).fetchall()\\n        if len(mapping)!=1:return (\\\'NO_UNIQUE_ORIGINAL_MARKET_MAPPING\\\',)\\n        evroot,event,fac,point=mapping[0]\\n        if str(evroot)!=str(root) or str(event)!=str(root):\\n            return (\\\'QUOTE_ROOT_MARKET_MISMATCH\\\',)\\n        if not quote_semantics(self.v5,market,selection,fac,point):\\n            return (\\\'MARKET_SEMANTICS_NOT_PROVEN\\\',)\\n        try:state=self.settlement._market_outcome(market,selection,int(espn[\\\'hs\\\']),int(espn[\\\'as\\\']))\\n        except Exception:return (\\\'NATIVE_MARKET_OUTCOME_ERROR\\\',)\\n        if state not in (\\\'WIN\\\',\\\'LOSS\\\',\\\'PUSH\\\'):\\n            return (\\\'NATIVE_MARKET_OUTCOME_UNKNOWN\\\',)\\n        value=round(float(stake)*(float(odds)-1),6) if state==\\\'WIN\\\' else (-float(stake) if state==\\\'LOSS\\\' else 0.0)\\n        return (\\\'OK\\\',state,value)\\n\\n    def report(self):\\n        report={\\\'gate\\\':\\\'ADDITIONAL_QUOTE_AND_NATIVE_MARKET_DRY_RUN\\\',\\n           \\\'strict_candidates_processed\\\':self.candidates,\\\'preview_settleable\\\':sum(self.outcomes.values()),\\n           \\\'outcomes\\\':dict(self.outcomes), \\\'preview_stake_usd\\\':round(self.stake,4),\\n           \\\'preview_net_profit_usd\\\':round(self.profit,4),\\n           \\\'preview_roi_pct\\\':round(100*self.profit/self.stake,4) if self.stake else None,\\n           \\\'preview_distinct_events\\\':len(self.events), \\\'rejections\\\':dict(self.reasons),\\n           \\\'by_league\\\':dict(self.leagues), \\\'examples_sha8\\\':self.examples,\\n           \\\'missing_schema_or_runtime\\\':self.missing,\\\'real_orders\\\':0,\\\'db_writes\\\':0}\\n        print(\\\'R7_3_PNL_PREVIEW\\\',json.dumps(report,ensure_ascii=False,sort_keys=True),flush=True)\\n        return report\\n\\n\\n#!/usr/bin/env python3\\n"""EVA R7.2: strict results and safe redirect audit. NO DATABASE WRITES."""\\nimport collections\\nimport csv\\nimport datetime as dt\\nimport difflib\\nimport io\\nimport json\\nimport re\\nimport sqlite3\\nimport sys\\nimport time\\nimport unicodedata\\nimport urllib.error\\nimport urllib.request\\nfrom urllib.parse import urlsplit, urljoin\\n\\nDB=\\\'file:/data/oracle.sqlite3?mode=ro\\\'\\nDIVS={\\n \\\'en.1\\\':(\\\'E0\\\',\\\'eng.1\\\'), \\\'en.2\\\':(\\\'E1\\\',\\\'eng.2\\\'),\\n \\\'it.1\\\':(\\\'I1\\\',\\\'ita.1\\\'), \\\'de.1\\\':(\\\'D1\\\',\\\'ger.1\\\'),\\n \\\'fr.1\\\':(\\\'F1\\\',\\\'fra.1\\\'), \\\'es.1\\\':(\\\'SP1\\\',\\\'esp.1\\\'),\\n \\\'pt.1\\\':(\\\'P1\\\',\\\'por.1\\\'), \\\'nl.1\\\':(\\\'N1\\\',\\\'ned.1\\\')\\n}\\n# Explicit verified name variants; proposals still require two agreeing independent providers.\\nALIASES={\\n \\\'stade rennais 1901\\\':\\\'rennes\\\', \\\'stade rennais\\\':\\\'rennes\\\', \\\'rennais\\\':\\\'rennes\\\',\\n \\\'lille\\\':\\\'lille\\\',\\\'lille olympique sporting\\\':\\\'lille\\\',\\n \\\'fc internazionale milano\\\':\\\'inter\\\',\\\'internazionale milano\\\':\\\'inter\\\',\\\'internazionale\\\':\\\'inter\\\',\\n \\\'como 1907\\\':\\\'como\\\', \\\'real betis balompie\\\':\\\'betis\\\',\\\'real betis\\\':\\\'betis\\\',\\\'betis\\\':\\\'betis\\\',\\n \\\'atletico madrid\\\':\\\'atletico madrid\\\',\\\'atletico de madrid\\\':\\\'atletico madrid\\\',\\n \\\'fc barcelona\\\':\\\'barcelona\\\',\\\'barcelona\\\':\\\'barcelona\\\',\\n \\\'elche\\\':\\\'elche\\\', \\\'real sociedad de futbol\\\':\\\'real sociedad\\\',\\n \\\'rayo vallecano de madrid\\\':\\\'rayo vallecano\\\',\\n \\\'stade brestois 29\\\':\\\'brest\\\',\\\'olympique lyonnais\\\':\\\'lyon\\\',\\n \\\'olympique de marseille\\\':\\\'marseille\\\',\\\'racing club de lens\\\':\\\'lens\\\',\\n \\\'ogc nice\\\':\\\'nice\\\',\\\'angers sco\\\':\\\'angers\\\',\\n \\\'le havre ac\\\':\\\'le havre\\\',\\\'fc lorient\\\':\\\'lorient\\\',\\n \\\'ac monza\\\':\\\'monza\\\',\\\'atalanta bc\\\':\\\'atalanta\\\',\\n \\\'ac fiorentina\\\':\\\'fiorentina\\\', \\\'juventus fc\\\':\\\'juventus\\\',\\n \\\'rc celta de vigo\\\':\\\'celta vigo\\\',\\\'celta\\\':\\\'celta vigo\\\',\\n \\\'levante ud\\\':\\\'levante\\\', \\\'villarreal cf\\\':\\\'villarreal\\\',\\n \\\'getafe cf\\\':\\\'getafe\\\', \\\'inter milan\\\':\\\'inter\\\',\\n \\\'man united\\\':\\\'manchester united\\\',\\\'man utd\\\':\\\'manchester united\\\',\\n \\\'man city\\\':\\\'manchester city\\\',\\\'manchester utd\\\':\\\'manchester united\\\',\\n \\\'wolves\\\':\\\'wolverhampton\\\', \\\'spurs\\\':\\\'tottenham\\\',\\n \\\'bournemouth\\\':\\\'bournemouth\\\', \\\'brighton\\\':\\\'brighton\\\',\\n \\\'nottm forest\\\':\\\'nottingham forest\\\',\\\'nottingham\\\':\\\'nottingham forest\\\',\\n \\\'newcastle\\\':\\\'newcastle united\\\', \\\'leeds\\\':\\\'leeds united\\\',\\n \\\'west ham\\\':\\\'west ham united\\\', \\\'leicester\\\':\\\'leicester city\\\',\\n \\\'ipswich\\\':\\\'ipswich town\\\',\\\'hull\\\':\\\'hull city\\\', \\\'coventry\\\':\\\'coventry city\\\',\\n \\\'sheffield utd\\\':\\\'sheffield united\\\',\\\'sheffield weds\\\':\\\'sheffield wednesday\\\',\\n \\\'qpr\\\':\\\'queens park rangers\\\',\\\'cardiff\\\':\\\'cardiff city\\\',\\n \\\'birmingham\\\':\\\'birmingham city\\\',\\\'stoke\\\':\\\'stoke city\\\',\\n \\\'norwich\\\':\\\'norwich city\\\',\\\'bristol city\\\':\\\'bristol city\\\',\\n \\\'koln\\\':\\\'cologne\\\', \\\'1 koln\\\':\\\'cologne\\\',\\\'fc koln\\\':\\\'cologne\\\',\\n \\\'bayer 04 leverkusen\\\':\\\'bayer leverkusen\\\',\\\'bayer leverkusen\\\':\\\'bayer leverkusen\\\',\\n \\\'union berlin\\\':\\\'union berlin\\\',\\\'freiburg\\\':\\\'freiburg\\\',\\n \\\'wolfsburg\\\':\\\'wolfsburg\\\',\\\'borussia dortmund\\\':\\\'dortmund\\\',\\n \\\'borussia monchengladbach\\\':\\\'monchengladbach\\\',\\n \\\'rb leipzig\\\':\\\'leipzig\\\',\\\'red bull leipzig\\\':\\\'leipzig\\\',\\n \\\'bayern munchen\\\':\\\'bayern munich\\\',\\\'bayern munich\\\':\\\'bayern munich\\\',\\n \\\'psg\\\':\\\'paris saint germain\\\',\\\'paris sg\\\':\\\'paris saint germain\\\',\\n \\\'paris saint germain\\\':\\\'paris saint germain\\\',\\n \\\'az alkmaar\\\':\\\'az\\\',\\\'psv eindhoven\\\':\\\'psv\\\',\\\'ajax amsterdam\\\':\\\'ajax\\\',\\n \\\'sporting lisbon\\\':\\\'sporting cp\\\',\\\'sporting portugal\\\':\\\'sporting cp\\\',\\n \\\'porto\\\':\\\'porto\\\',\\\'fc porto\\\':\\\'porto\\\', \\\'benfica\\\':\\\'benfica\\\',\\n}\\nFILLER={\\\'fc\\\',\\\'cf\\\',\\\'afc\\\',\\\'ac\\\',\\\'sc\\\',\\\'ssc\\\',\\\'osc\\\',\\\'the\\\',\\\'football\\\',\\\'club\\\',\\\'futbol\\\',\\\'de\\\',\\\'del\\\',\\\'da\\\',\\\'do\\\',\\\'du\\\',\\\'fk\\\',\\\'sk\\\',\\\'sv\\\'}\\nMAX_BYTES=2500000\\n\\n\\ndef namekey(s):\\n    s=unicodedata.normalize(\\\'NFKD\\\',str(s or \\\'\\\')).casefold()\\n    s=\\\'\\\'.join(c for c in s if not unicodedata.combining(c))\\n    s=s.replace(\\\'ø\\\',\\\'o\\\').replace(\\\'æ\\\',\\\'ae\\\').replace(\\\'ß\\\',\\\'ss\\\').replace(\\\'ł\\\',\\\'l\\\')\\n    s=re.sub(r\\\'[^a-z0-9 ]\\\',\\\' \\\',s)\\n    s=\\\' \\\'.join(s.split())\\n    if s in ALIASES: return ALIASES[s]\\n    s=\\\' \\\'.join(p for p in s.split() if p not in FILLER)\\n    return ALIASES.get(s,s)\\n\\n# Only these official source hosts are trusted. A redirect is accepted only\\n# when the CSV provider switches between its explicitly allowed apex/www host.\\n_ALLOWED_HOSTS = frozenset((\\\'site.api.espn.com\\\', \\\'www.football-data.co.uk\\\', \\\'football-data.co.uk\\\'))\\n_FOOTBALL_HOSTS = frozenset((\\\'www.football-data.co.uk\\\', \\\'football-data.co.uk\\\'))\\n\\n\\ndef _validate_endpoint(url):\\n    p=urlsplit(url)\\n    if (p.scheme.lower() != \\\'https\\\' or p.hostname not in _ALLOWED_HOSTS\\n            or p.username is not None or p.password is not None\\n            or p.port not in (None, 443) or p.fragment):\\n        raise ValueError(\\\'HOST_OR_HTTPS_NOT_ALLOWLISTED\\\')\\n    return p\\n\\n\\ndef _validate_redirect(old, new):\\n    p=_validate_endpoint(old)\\n    q=_validate_endpoint(new)\\n    if p.hostname not in _FOOTBALL_HOSTS or q.hostname not in _FOOTBALL_HOSTS:\\n        raise ValueError(\\\'REDIRECT_PROVIDER_NOT_ALLOWED\\\')\\n    if (p.path, p.query) != (q.path, q.query):\\n        raise ValueError(\\\'REDIRECT_CHANGED_CSV_PATH_OR_QUERY\\\')\\n    return new\\n\\n\\nclass _SafeRedirectHandler(urllib.request.HTTPRedirectHandler):\\n    def redirect_request(self, req, fp, code, msg, headers, newurl):\\n        # Validation occurs before urllib may connect to redirect destination.\\n        _validate_redirect(req.full_url, newurl)\\n        return super().redirect_request(req, fp, code, msg, headers, newurl)\\n\\n\\ndef fetch(url,timeout=7):\\n    _validate_endpoint(url)\\n    req=urllib.request.Request(url,headers={\\\'User-Agent\\\':\\\'Oracle-EVA-R7/1.2 (research-only)\\\',\\\'Accept\\\':\\\'application/json,text/csv\\\'})\\n    with urllib.request.build_opener(_SafeRedirectHandler()).open(req,timeout=timeout) as resp:\\n        _validate_endpoint(resp.geturl())\\n        if resp.status!=200:raise ValueError(\\\'HTTP_\\\'+str(resp.status))\\n        b=resp.read(MAX_BYTES+1)\\n        if len(b)>MAX_BYTES:raise ValueError(\\\'RESPONSE_TOO_LARGE\\\')\\n        return b\\n\\ndef parse_date(s):\\n    s=(s or \\\'\\\').strip()\\n    for fmt in (\\\'%d/%m/%Y\\\',\\\'%d/%m/%y\\\',\\\'%Y-%m-%d\\\',\\\'%d/%m/%Y %H:%M\\\'):\\n        try:return dt.datetime.strptime(s,fmt).date()\\n        except ValueError:pass\\n    return None\\n\\ndef csv_rows(raw):\\n    s=raw.decode(\\\'utf-8-sig\\\',errors=\\\'replace\\\')\\n    if \\\'<html\\\' in s[:300].lower():raise ValueError(\\\'HTML_INSTEAD_OF_CSV\\\')\\n    out=[]\\n    for r in csv.DictReader(io.StringIO(s)):\\n        try:\\n            d=parse_date(r.get(\\\'Date\\\',\\\'\\\'))\\n            if not d:continue\\n            h=r.get(\\\'FTHG\\\');a=r.get(\\\'FTAG\\\')\\n            if h is None or a is None or not h.strip() or not a.strip():continue\\n            if not (h.strip().isdigit() and a.strip().isdigit()):continue\\n            hi=int(h);ai=int(a)\\n            if hi>30 or ai>30:continue\\n            if r.get(\\\'FTR\\\',\\\'\\\') not in (\\\'H\\\',\\\'D\\\',\\\'A\\\'):continue\\n            if r[\\\'FTR\\\']!=(\\\'H\\\' if hi>ai else \\\'D\\\' if hi==ai else \\\'A\\\'):continue\\n            home=(r.get(\\\'HomeTeam\\\') or \\\'\\\').strip();away=(r.get(\\\'AwayTeam\\\') or \\\'\\\').strip()\\n            if home and away:out.append({\\\'date\\\':d,\\\'home\\\':home,\\\'away\\\':away,\\\'hs\\\':hi,\\\'as\\\':ai})\\n        except (ValueError,KeyError,TypeError):pass\\n    return out\\n\\ndef espn_rows(raw):\\n    obj=json.loads(raw)\\n    out=[]\\n    for ev in obj.get(\\\'events\\\',[]):\\n        st=(ev.get(\\\'status\\\') or {}).get(\\\'type\\\') or {}\\n        comps=ev.get(\\\'competitions\\\') or []\\n        if not comps or st.get(\\\'completed\\\') is not True or st.get(\\\'state\\\')!=\\\'post\\\':continue\\n        co=comps[0];teams={}\\n        for comp in co.get(\\\'competitors\\\',[]):\\n            side=comp.get(\\\'homeAway\\\')\\n            if side not in (\\\'home\\\',\\\'away\\\'):continue\\n            team=comp.get(\\\'team\\\') or {}\\n            name=team.get(\\\'displayName\\\') or team.get(\\\'name\\\')\\n            try:\\n                val=float(comp[\\\'score\\\'])\\n                if not val.is_integer() or not 0<=val<=30:continue\\n            except (KeyError,TypeError,ValueError):continue\\n            teams[side]=(name,int(val))\\n        if set(teams)!={\\\'home\\\',\\\'away\\\'}:continue\\n        try:\\n            kickoff=dt.datetime.fromisoformat((ev.get(\\\'date\\\') or co.get(\\\'date\\\')).replace(\\\'Z\\\',\\\'+00:00\\\'))\\n            if kickoff.tzinfo is None:continue\\n            kickoff=kickoff.astimezone(dt.timezone.utc)\\n        except (TypeError,ValueError,AttributeError):continue\\n        out.append({\\\'date\\\':kickoff.date(),\\\'home\\\':teams[\\\'home\\\'][0],\\\'away\\\':teams[\\\'away\\\'][0],\\n                    \\\'hs\\\':teams[\\\'home\\\'][1],\\\'as\\\':teams[\\\'away\\\'][1],\\n                    \\\'event_id\\\':str(ev.get(\\\'id\\\',\\\'\\\')),\\n                    \\\'kickoff_utc\\\':kickoff.isoformat(timespec=\\\'seconds\\\')})\\n    return out\\n\\ndef pick(target,results):\\n    # STRICT full team matching only. No fuzzy auto-approval.\\n    h=namekey(target[\\\'home\\\']);a=namekey(target[\\\'away\\\']);day=target[\\\'date\\\']\\n    items=[]\\n    for r in results:\\n        if abs((r[\\\'date\\\']-day).days)>1:continue\\n        if namekey(r[\\\'home\\\'])==h and namekey(r[\\\'away\\\'])==a:\\n            items.append(r)\\n    if not items:return None\\n    scores={(r[\\\'hs\\\'],r[\\\'as\\\']) for r in items}\\n    if len(scores)!=1:return {\\\'error\\\':\\\'MULTIPLE_DIFFERENT_SCORES\\\'}\\n    # Scoreboard requests for adjacent days can repeat the SAME event ID.\\n    # More than one distinct event ID is unresolvable, even with the same score.\\n    events={r.get(\\\'event_id\\\') for r in items if r.get(\\\'event_id\\\')}\\n    if len(events)>1:return {\\\'error\\\':\\\'MULTIPLE_EVENT_IDS\\\'}\\n    ids={(r[\\\'date\\\'],namekey(r[\\\'home\\\']),namekey(r[\\\'away\\\'])) for r in items}\\n    if len(ids)>1:return {\\\'error\\\':\\\'MULTIPLE_MATCH_DATES\\\'}\\n    return items[0]\\n\\ndef utc_stamp(s):\\n    try:\\n        d=dt.datetime.fromisoformat(str(s).replace(\\\'Z\\\',\\\'+00:00\\\'))\\n        return d.astimezone(dt.timezone.utc) if d.tzinfo else None\\n    except (TypeError,ValueError,OverflowError):\\n        return None\\n\\n\\ndef strict_gate(db, fixture, espn, csv, at):\\n    """READ ONLY: gate each PENDING forecast and return counts, never settle.\\n\\n    Requires fresh two-provider consensus plus ESPN kickoff within ten minutes\\n    of the exact pre-registered paper kickoff. Missing/malformed quote/creation\\n    timestamps are blocked rather than silently assumed.\\n    """\\n    if not espn or not csv or \\\'error\\\' in espn or \\\'error\\\' in csv:\\n        return collections.Counter({\\\'NO_TWO_SOURCE_CONSENSUS\\\':1}), 0\\n    if (espn[\\\'hs\\\'],espn[\\\'as\\\']) != (csv[\\\'hs\\\'],csv[\\\'as\\\']):\\n        return collections.Counter({\\\'SOURCE_SCORE_CONFLICT\\\':1}), 0\\n    cols={r[1] for r in db.execute(\\\'PRAGMA table_info(v55_paper)\\\')}\\n    must={\\\'forecast_id\\\',\\\'original_event_id\\\',\\\'origin\\\',\\\'status\\\',\\\'kickoff_utc\\\',\\n          \\\'quote_at\\\',\\\'registered_at\\\',\\\'odds\\\',\\\'stake\\\',\\\'result_home\\\',\\\'result_away\\\'}\\n    if not must.issubset(cols):\\n        raise RuntimeError(\\\'MISSING_PAPER_COLUMNS \\\'+\\\',\\\'.join(sorted(must-cols)))\\n    match=db.execute("SELECT source,home_score,away_score FROM sf_matches WHERE id=?",\\n                     (fixture[\\\'id\\\'],)).fetchone()\\n    if not match or not str(match[0]).lower().startswith(\\\'openfootball\\\'):\\n        return collections.Counter({\\\'INVALID_ORIGINAL_SOURCE\\\':1}),0\\n    if (match[1] is None)!=(match[2] is None):\\n        return collections.Counter({\\\'PARTIAL_PRIOR_SCORE\\\':1}),0\\n    if match[1] is not None:\\n        if (int(match[1]),int(match[2]))!=(espn[\\\'hs\\\'],espn[\\\'as\\\']):\\n            return collections.Counter({\\\'CONFLICT_WITH_ORIGINAL_SCORE\\\':1}),0\\n    conflicts=db.execute("""SELECT COUNT(*) FROM v55_paper\\n          WHERE origin=\\\'sf_forecasts\\\' AND original_event_id=?\\n          AND status IN (\\\'WIN\\\',\\\'LOSS\\\',\\\'PUSH\\\')\\n          AND result_home IS NOT NULL AND result_away IS NOT NULL\\n          AND (result_home!=? OR result_away!=?)""",\\n          (fixture[\\\'id\\\'],espn[\\\'hs\\\'],espn[\\\'as\\\'])).fetchone()[0]\\n    if conflicts:\\n        return collections.Counter({\\\'CONFLICT_WITH_SETTLED_PAPER\\\':conflicts}),0\\n    rows=db.execute("""SELECT forecast_id,kickoff_utc,quote_at,registered_at,odds,stake\\n      FROM v55_paper WHERE origin=\\\'sf_forecasts\\\' AND original_event_id=? AND status=\\\'PENDING\\\' """,\\n      (fixture[\\\'id\\\'],)).fetchall()\\n    counts=collections.Counter()\\n    event_kick=utc_stamp(espn.get(\\\'kickoff_utc\\\'))\\n    now=utc_stamp(at)\\n    if not event_kick or not now or not str(espn.get(\\\'event_id\\\') or \\\'\\\').isdigit():\\n        return collections.Counter({\\\'INVALID_EVENT_ID_OR_CLOCK\\\':len(rows)}),0\\n    if now<event_kick+dt.timedelta(minutes=95):\\n        return collections.Counter({\\\'FINAL_TOO_RECENT\\\':len(rows)}),0\\n    if abs((csv[\\\'date\\\']-espn[\\\'date\\\']).days)>1:\\n        return collections.Counter({\\\'SOURCE_DATE_DISAGREEMENT\\\':len(rows)}),0\\n    for forecast_id,kick,quote,registered,odds,stake in rows:\\n        k,q,r=utc_stamp(kick),utc_stamp(quote),utc_stamp(registered)\\n        if not k:\\n            reason=\\\'NO_PAPER_KICKOFF\\\'\\n        elif abs((k-event_kick).total_seconds())>600:\\n            reason=\\\'KICKOFF_MISMATCH_OVER_10_MIN\\\'\\n        elif not r or r>=k:\\n            reason=\\\'REGISTRATION_NOT_PREKICKOFF\\\'\\n        elif not q or q>=k:\\n            reason=\\\'QUOTE_NOT_PREKICKOFF\\\'\\n        elif not (isinstance(odds,(int,float)) and odds>1 and isinstance(stake,(int,float)) and stake>0):\\n            reason=\\\'INVALID_ODDS_OR_STAKE\\\'\\n        elif now<k+dt.timedelta(minutes=95):\\n            reason=\\\'NOT_ENOUGH_SETTLEMENT_TIME\\\'\\n        else:\\n            reason=\\\'STRICT_ELIGIBLE\\\'\\n        counts[reason]+=1\\n    return counts,len(rows)\\n\\n\\ndef audit(db,fetcher=fetch,limit_requests=115,verbose=True):\\n    now=dt.datetime.now(dt.timezone.utc).isoformat(timespec=\\\'seconds\\\')\\n    rows=db.execute(\\\'\\\'\\\'SELECT DISTINCT s.id,s.league,s.season,s.match_date,s.home,s.away\\n      FROM v55_paper p JOIN sf_matches s ON s.id=p.original_event_id\\n      WHERE p.origin=\\\'sf_forecasts\\\' AND p.status=\\\'PENDING\\\' AND p.kickoff_utc < ?\\n      AND s.sport=\\\'football\\\' ORDER BY s.league,s.match_date,s.id\\\'\\\'\\\',(now,)).fetchall()\\n    targets=[]\\n    for mid,league,season,day,home,away in rows:\\n        date=parse_date(day)\\n        if date:targets.append({\\\'id\\\':mid,\\\'league\\\':league,\\\'season\\\':season,\\\'date\\\':date,\\\'home\\\':home,\\\'away\\\':away})\\n    print(\\\'EVA_R7_6_CAPTURE_TIMESTAMP_READ_ONLY\\\',now,\\\'sf_football_fixtures\\\',len(targets),flush=True)\\n    csv_cache={};espn_cache={};errors=[];calls=0\\n    seasons=sorted({(t[\\\'league\\\'],t[\\\'season\\\']) for t in targets if t[\\\'league\\\'] in DIVS})\\n    for league,season in seasons:\\n        if not re.fullmatch(r\\\'20\\\\d\\\\d-\\\\d\\\\d\\\',str(season)):\\n            errors.append({\\\'source\\\':\\\'CSV\\\',\\\'league\\\':league,\\\'reason\\\':\\\'INVALID_SEASON\\\'});continue\\n        code=season[2:4]+season[5:7]\\n        url=\\\'https://www.football-data.co.uk/mmz4281/\\\'+code+\\\'/\\\'+DIVS[league][0]+\\\'.csv\\\'\\n        if calls>=limit_requests:errors.append({\\\'source\\\':\\\'CSV\\\',\\\'league\\\':league,\\\'reason\\\':\\\'REQUEST_LIMIT\\\'});continue\\n        try:\\n            calls+=1;csv_cache[(league,season)]=csv_rows(fetcher(url));\\n            print(\\\'CSV_FETCH\\\',league,season,len(csv_cache[(league,season)]),flush=True)\\n        except Exception as e:\\n            errors.append({\\\'source\\\':\\\'CSV\\\',\\\'league\\\':league,\\\'reason\\\':str(e)[:180]});csv_cache[(league,season)]=[]\\n    pairs=set()\\n    for t in targets:\\n        if t[\\\'league\\\'] not in DIVS:continue\\n        for delta in (-1,0,1):\\n            day=t[\\\'date\\\']+dt.timedelta(days=delta)\\n            if day>dt.datetime.now(dt.timezone.utc).date():continue\\n            pairs.add((t[\\\'league\\\'],day))\\n    for league,day in sorted(pairs):\\n        if calls>=limit_requests:\\n            errors.append({\\\'source\\\':\\\'ESPN\\\',\\\'reason\\\':\\\'REQUEST_LIMIT_REACHED\\\',\\\'skipped\\\':len(pairs)-len(espn_cache)})\\n            break\\n        slug=DIVS[league][1]\\n        url=f\\\'https://site.api.espn.com/apis/site/v2/sports/soccer/{slug}/scoreboard?dates={day:%Y%m%d}&limit=150\\\'\\n        try:\\n            calls+=1;espn_cache[(league,day)]=espn_rows(fetcher(url));\\n        except Exception as e:\\n            errors.append({\\\'source\\\':\\\'ESPN\\\',\\\'league\\\':league,\\\'day\\\':str(day),\\\'reason\\\':str(e)[:180]});espn_cache[(league,day)]=[]\\n        time.sleep(.12)\\n    summary=collections.Counter(); bets=collections.Counter()\\n    gates=collections.Counter(); gate_fixtures=collections.Counter()\\n    preview=Preview(db)\\n    for t in targets:\\n        pool=[]\\n        for delta in (-1,0,1):pool+=espn_cache.get((t[\\\'league\\\'],t[\\\'date\\\']+dt.timedelta(days=delta)),[])\\n        e=pick(t,pool); f=pick(t,csv_cache.get((t[\\\'league\\\'],t[\\\'season\\\']),[]))\\n        if (e and \\\'error\\\' in e) or (f and \\\'error\\\' in f):state=\\\'AMBIGUOUS\\\'\\n        elif e and f and (e[\\\'hs\\\'],e[\\\'as\\\'])==(f[\\\'hs\\\'],f[\\\'as\\\']):state=\\\'TWO_SOURCE_AGREEMENT\\\'\\n        elif e and f:state=\\\'SOURCE_CONFLICT\\\'\\n        elif e:state=\\\'ESPN_ONLY\\\'\\n        elif f:state=\\\'CSV_ONLY\\\'\\n        else:state=\\\'NO_MATCH\\\'\\n        summary[state]+=1\\n        count=db.execute("SELECT COUNT(*) FROM v55_paper WHERE origin=\\\'sf_forecasts\\\' AND original_event_id=? AND status=\\\'PENDING\\\' AND kickoff_utc<?",(t[\\\'id\\\'],now)).fetchone()[0]\\n        bets[state]+=count\\n        if state==\\\'TWO_SOURCE_AGREEMENT\\\':\\n            one,total=strict_gate(db,t,e,f,now)\\n            gates.update(one)\\n            preview.check(t,e,f,one,total,now)\\n            if one.get(\\\'STRICT_ELIGIBLE\\\')==total and total>0:\\n                gate_fixtures[\\\'ALL_STRICT_ELIGIBLE\\\']+=1\\n            elif one.get(\\\'STRICT_ELIGIBLE\\\'):\\n                gate_fixtures[\\\'PARTIAL_STRICT_ELIGIBLE\\\']+=1\\n            else:\\n                gate_fixtures[\\\'NONE_STRICT_ELIGIBLE\\\']+=1\\n            if verbose:\\n                print(\\\'STRICT_FIXTURE_GATE\\\',json.dumps({\\\'league\\\':t[\\\'league\\\'],\\\'date\\\':str(t[\\\'date\\\']),\\n                     \\\'home\\\':t[\\\'home\\\'],\\\'away\\\':t[\\\'away\\\'],\\\'bets\\\':total,\\n                     \\\'espn_kickoff_utc\\\':e.get(\\\'kickoff_utc\\\'),\\n                     \\\'gate_counts\\\':dict(one)},ensure_ascii=False,sort_keys=True),flush=True)\\n        if verbose:\\n            detail={\\\'league\\\':t[\\\'league\\\'],\\\'date\\\':str(t[\\\'date\\\']),\\\'home\\\':t[\\\'home\\\'],\\\'away\\\':t[\\\'away\\\'],\\n                    \\\'state\\\':state,\\\'paper_bets\\\':count,\\n                    \\\'espn_score\\\':([e[\\\'hs\\\'],e[\\\'as\\\']] if e and \\\'hs\\\' in e else None),\\n                    \\\'csv_score\\\':([f[\\\'hs\\\'],f[\\\'as\\\']] if f and \\\'hs\\\' in f else None),\\n                    \\\'espn_event_id\\\':e.get(\\\'event_id\\\') if e and \\\'hs\\\' in e else None}\\n            print(\\\'FIXTURE\\\',json.dumps(detail,ensure_ascii=False),flush=True)\\n    print(\\\'SOURCE_REQUESTS\\\',calls,\\\'ESPN_DATE_GROUPS\\\',len(espn_cache),\\\'CSV_LEAGUE_SEASONS\\\',len(csv_cache),flush=True)\\n    print(\\\'RESULT_FIXTURES\\\',json.dumps(dict(summary),sort_keys=True),flush=True)\\n    print(\\\'RESULT_PAPER_BETS\\\',json.dumps(dict(bets),sort_keys=True),flush=True)\\n    print(\\\'STRICT_GATE_BETS\\\',json.dumps(dict(gates),sort_keys=True),flush=True)\\n    print(\\\'STRICT_ELIGIBLE_BETS\\\',gates.get(\\\'STRICT_ELIGIBLE\\\',0),flush=True)\\n    print(\\\'STRICT_GATE_FIXTURES\\\',json.dumps(dict(gate_fixtures),sort_keys=True),flush=True)\\n    preview.report()\\n    preview.diagnostic_report()\\n    r76 = preview.capture_provenance_report()\\n    print(\\\'R7_6_METADATA_TIMESTAMP_CHECK\\\',json.dumps({\\n       \\\'packets_timestamp_column\\\':r76[\\\'metadata_packet\\\'].get(\\\'timestamp_column\\\'),\\n       \\\'packets_status\\\':r76[\\\'metadata_packet\\\'].get(\\\'status\\\'),\\n       \\\'runs_timestamp_column\\\':r76[\\\'metadata_runs\\\'].get(\\\'timestamp_column\\\'),\\n       \\\'runs_status\\\':r76[\\\'metadata_runs\\\'].get(\\\'status\\\'),\\n       \\\'global_packet_within_60s\\\':r76[\\\'packet_within_60s\\\'],\\n       \\\'global_packet_within_10min\\\':r76[\\\'packet_within_10min\\\'],\\n       \\\'parent_discrepancies\\\':r76[\\\'r7_6_parent_discrepancies\\\'],\\n       \\\'no_bet_promotions\\\':True,\\\'db_writes\\\':0},sort_keys=True),flush=True)\\n    print(\\\'ERRORS\\\',json.dumps(errors[:30],ensure_ascii=False),flush=True)\\n    print(\\\'WARNING R7.6 FORENSICS: no SQLite writes, no settlement, no real orders. Historical price interpolation is NOT permission to settle.\\\',flush=True)\\n    print(\\\'WARNING Strict eligibility is a preliminary mechanical gate, NOT permission to write to SQLite.\\\',flush=True)\\n    print(\\\'WARNING Source independence, fixture identity, bookmaker quote provenance and market semantics require final audit.\\\',flush=True)\\n    return dict(summary)\\n\\ndef main():\\n    db=sqlite3.connect(DB,uri=True,timeout=5)\\n    db.execute(\\\'PRAGMA query_only=ON\\\')\\n    try:\\n        audit(db,verbose=False)\\n    finally:db.close()\\n\\nif __name__==\\\'__main__\\\':main()\\n\',\'<bundled_audit>\',\'exec\'),a.__dict__)\n\nDB=Path(\'/data/oracle.sqlite3\')\nBACKUPS=Path(\'/data/eva-backups\')\nSOURCE=\'EVA_R8_ESPN_FOOTBALLDATA_FINAL_EXACT_QUOTE\'\nNATIVE_SHAS={\n  \'/app/oracle_v5.py\':\'b243e223efdbe48b931dfa26bec729261885dbd0ca87a8ea07c24e5418d6ae1c\',\n  \'/app/oracle_v5_settlement.py\':\'a22936af760b26e0cbed3eacdea5f3a6ade0f757e4297caf6a881a3dca3ecf2f\',\n}\nPAPER_COLS=(\'forecast_id\',\'root_id\',\'original_event_id\',\'origin\',\'market\',\'selection\',\n            \'odds\',\'stake\',\'quote_key\',\'quote_at\',\'registered_at\',\'kickoff_utc\',\n            \'status\',\'result_home\',\'result_away\',\'result_seen\',\'settled_at\',\'profit\',\'source\')\nOUTCOME_COLS=(\'status\',\'result_home\',\'result_away\',\'result_seen\',\'settled_at\',\'profit\',\'source\')\n\n\ndef msg(label, payload):\n    print(label, json.dumps(payload, ensure_ascii=False, sort_keys=True, default=str), flush=True)\n\n\ndef validate_target():\n    if not DB.is_file() or not DB.resolve().as_posix() == \'/data/oracle.sqlite3\':\n        raise RuntimeError(\'EVA_DB_PATH_NOT_EXACT\')\n    if not Path(\'/runner/probe.py\').is_file():\n        raise RuntimeError(\'EVA_PROBE_NOT_MOUNTED\')\n    code=Path(\'/runner/probe.py\').read_text(encoding=\'utf-8\')\n    if \'verified_paper_settlement\' not in code:\n        raise RuntimeError(\'EVA_R6_SETTLEMENT_TASK_NOT_PRESENT\')\n    for fname,sha in NATIVE_SHAS.items():\n        if not Path(fname).is_file() or hashlib.sha256(Path(fname).read_bytes()).hexdigest()!=sha:\n            raise RuntimeError(\'SOURCE_SHA_MISMATCH_OR_MISSING:\'+fname)\n    if os.environ.get(\'EVA_RUN_MODE\') not in (\'apply\',\'rollback\'):\n        raise RuntimeError(\'RUN_MODE_NOT_EXPLICIT\')\n    stat=os.statvfs(\'/data\');free=stat.f_bavail*stat.f_frsize;size=DB.stat().st_size\n    if os.environ.get(\'EVA_RUN_MODE\')==\'apply\' and free < max(12*1024**3, size*2+1024**3):\n        raise RuntimeError(\'INSUFFICIENT_DISK_FOR_ONLINE_BACKUP\')\n    if size<1024*1024 or size>500*1024**3:\n        raise RuntimeError(\'SUSPICIOUS_DB_SIZE\')\n    con=sqlite3.connect(f\'file:{DB}?mode=ro\',uri=True,timeout=30)\n    con.execute(\'PRAGMA query_only=ON\')\n    try:\n        tables={r[0] for r in con.execute("SELECT name FROM sqlite_master WHERE type=\'table\'")}\n        required={\'sf_matches\',\'v55_paper\',\'v55_settlement_runs\',\'v5_forecasts\',\n                  \'fb_full_history\',\'fb_full_current\'}\n        if not required.issubset(tables):\n            raise RuntimeError(\'REQUIRED_TABLE_MISSING:\'+str(sorted(required-tables)))\n        cols={r[1] for r in con.execute(\'PRAGMA table_info(v55_paper)\')}\n        if not set(PAPER_COLS).issubset(cols):\n            raise RuntimeError(\'PAPER_COLS_MISSING:\'+str(sorted(set(PAPER_COLS)-cols)))\n    finally:con.close()\n    BACKUPS.mkdir(mode=0o700,parents=True,exist_ok=True)\n    msg(\'EVA_TARGET_VERIFIED\',{\'db_bytes\':size,\'free_bytes\':free,\'modules_shas\':\'PASS\', \'mode\':os.environ[\'EVA_RUN_MODE\']})\n\n\nclass CandidateCollector(a.Preview):\n    latest=None\n    def __init__(self,db):\n        super().__init__(db)\n        self.ledger=[]\n        CandidateCollector.latest=self\n\n    def _check_one(self,fid,root,market,selection,odds,stake,qkey,qat,registered,kick,t,espn):\n        result=super()._check_one(fid,root,market,selection,odds,stake,qkey,qat,registered,kick,t,espn)\n        if result[0]!=\'OK\':return result\n        row=self.db.execute(\'\'\'SELECT price,quote_key,quote_snapshot\n            FROM v5_forecasts WHERE id=?\'\'\',(fid,)).fetchall()\n        if len(row)!=1:return (\'PARENT_PRICE_QUOTE_NOT_UNIQUE\',)\n        price,parent_key,parent_snapshot=row[0]\n        try:correct_price=(price is not None and abs(float(price)-float(odds))<1e-6)\n        except (ValueError,TypeError,OverflowError):correct_price=False\n        if not correct_price or str(parent_key)!=str(qkey) or a.clock(parent_snapshot)!=a.clock(qat):\n            return (\'PARENT_PRICE_OR_TIMESTAMP_NOT_IDENTICAL\',)\n        if espn[\'hs\']<0 or espn[\'as\']<0 or not str(espn[\'event_id\']).isdigit():\n            return (\'INVALID_FINAL_IDENTITY\',)\n        row=self.db.execute(\'SELECT \'+\',\'.join(PAPER_COLS)+\' FROM v55_paper WHERE forecast_id=?\',(fid,)).fetchall()\n        if len(row)!=1:return (\'PAPER_IDENTITY_NOT_UNIQUE\',)\n        old=dict(zip(PAPER_COLS,row[0]))\n        if old[\'status\']!=\'PENDING\' or old[\'original_event_id\']!=t[\'id\']:\n            return (\'PAPER_STATE_CHANGED\',)\n        state,profit=result[1:]\n        self.ledger.append({\n            \'forecast_id\':fid,\'original\':old,\'status\':state,\'profit\':profit,\n            \'hs\':espn[\'hs\'],\'as\':espn[\'as\'],\'espn_event_id\':espn[\'event_id\'],\n            \'espn_kickoff_utc\':espn[\'kickoff_utc\'],\'fixture\':t[\'id\'],\n            \'league\':t[\'league\'],\'home\':t[\'home\'],\'away\':t[\'away\'],\n            \'event_date\':str(t[\'date\'])})\n        return result\n\n\ndef collect_candidates(ro):\n    a.Preview=CandidateCollector\n    CandidateCollector.latest=None\n    buffer=io.StringIO()\n    with contextlib.redirect_stdout(buffer):\n        summary=a.audit(ro,limit_requests=115,verbose=False)\n    log=buffer.getvalue()\n    print(log,end=\'\',flush=True)\n    errors=None\n    for line in log.splitlines():\n        if line.startswith(\'ERRORS \'):\n            errors=json.loads(line[7:])\n    if errors is None or errors:\n        raise RuntimeError(\'EXTERNAL_RESULTS_AUDIT_INCOMPLETE_OR_ERRORS:\'+str(errors))\n    preview=CandidateCollector.latest\n    if not preview or preview.missing:\n        raise RuntimeError(\'NATIVE_PREVIEW_NOT_READY:\'+str(preview.missing if preview else None))\n    if len(preview.ledger)!=sum(preview.outcomes.values()):\n        raise RuntimeError(\'PREVIEW_LEDGER_MISMATCH\')\n    if len({r[\'forecast_id\'] for r in preview.ledger})!=len(preview.ledger):\n        raise RuntimeError(\'DUPLICATE_LEDGER_FORECAST_ID\')\n    msg(\'EVA_R8_GUARDED_PLAN\',{\'two_source_fixtures\':summary.get(\'TWO_SOURCE_AGREEMENT\'),\n        \'exact_quote_candidates\':len(preview.ledger),\'outcomes\':dict(preview.outcomes),\n        \'net_usd\':round(preview.profit,4), \'rejections\':dict(preview.reasons)})\n    return preview.ledger\n\n\ndef backup_online():\n    stamp=dt.datetime.now(dt.timezone.utc).strftime(\'%Y%m%dT%H%M%SZ\')\n    tag=f\'eva_r8_{stamp}_{uuid.uuid4().hex[:12]}\'\n    dbbackup=BACKUPS/(tag+\'.sqlite3\')\n    # O_EXCL prevents overwriting earlier backups even on repeated invocation.\n    fd=os.open(dbbackup,os.O_CREAT|os.O_EXCL|os.O_WRONLY,0o600)\n    os.close(fd)\n    try:\n        src=sqlite3.connect(f\'file:{DB}?mode=ro\',uri=True,timeout=30)\n        dst=sqlite3.connect(str(dbbackup),timeout=30)\n        try:src.backup(dst,pages=2048,sleep=0.1)\n        finally:dst.close();src.close()\n        dst=sqlite3.connect(f\'file:{dbbackup}?mode=ro\',uri=True,timeout=30)\n        try:\n            checked=dst.execute(\'PRAGMA quick_check\').fetchone()[0]\n            if checked!=\'ok\':raise RuntimeError(\'BACKUP_QUICK_CHECK_FAILED\')\n            rows=dst.execute(\'SELECT count(*) FROM v55_paper\').fetchone()[0]\n        finally:dst.close()\n        if dbbackup.stat().st_size<1024*1024:\n            raise RuntimeError(\'BACKUP_SUSPICIOUS_SIZE\')\n        msg(\'EVA_R8_SQLITE_ONLINE_BACKUP_OK\',{\'path\':str(dbbackup),\'size\':dbbackup.stat().st_size,\'paper_rows\':rows,\'quick_check\':\'ok\'})\n        return dbbackup,tag\n    except Exception:\n        # Keep any partial backup as .incomplete for forensic diagnosis; never reuse it.\n        try:dbbackup.rename(str(dbbackup)+\'.incomplete\')\n        except OSError:pass\n        raise\n\n\ndef manifest_write(path,obj):\n    tmp=path.with_name(\'.\'+path.name+\'.tmp\')\n    fd=os.open(tmp,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600)\n    try:\n        with os.fdopen(fd,\'w\',encoding=\'utf-8\') as f:\n            json.dump(obj,f,ensure_ascii=False,sort_keys=True,separators=(\',\',\':\'))\n            f.flush();os.fsync(f.fileno())\n        os.replace(tmp,path)\n    except Exception:\n        try:os.unlink(tmp)\n        except OSError:pass\n        raise\n\n\ndef row_state(c,fid):\n    rows=c.execute(\'SELECT \'+\',\'.join(PAPER_COLS)+\' FROM v55_paper WHERE forecast_id=?\',(fid,)).fetchall()\n    return None if len(rows)!=1 else dict(zip(PAPER_COLS,rows[0]))\n\n\ndef check_conflicting_existing(c,x):\n    h,aw=x[\'hs\'],x[\'as\'];fid=x[\'forecast_id\']\n    bad=c.execute(\'\'\'SELECT COUNT(*) FROM v55_paper\n       WHERE origin=\'sf_forecasts\' AND original_event_id=?\n       AND status IN (\'WIN\',\'LOSS\',\'PUSH\')\n       AND result_home IS NOT NULL AND result_away IS NOT NULL\n       AND (result_home!=? OR result_away!=?)\'\'\',(x[\'fixture\'],h,aw)).fetchone()[0]\n    if bad:raise RuntimeError(\'CONFLICT_WITH_EXISTING_SETTLED_SCORES:\'+str(fid))\n    orig=c.execute(\'SELECT home_score,away_score FROM sf_matches WHERE id=?\',(x[\'fixture\'],)).fetchone()\n    if not orig or (orig[0] is None)!=(orig[1] is None):\n        raise RuntimeError(\'MISSING_OR_PARTIAL_ORIGINAL_FIXTURE:\'+str(fid))\n    if orig[0] is not None and (orig[0],orig[1])!=(h,aw):\n        raise RuntimeError(\'CONFLICT_WITH_ORIGINAL_RESULT:\'+str(fid))\n\n\ndef guarded_apply(ledger):\n    if not ledger:\n        msg(\'EVA_R8_NO_CHANGES\',{\'reason\':\'ZERO_PROVEN_EXACT_QUOTE_CANDIDATES\'})\n        return {\'state\':\'NO_CHANGES\',\'changed\':0}\n    backup,tag=backup_online()\n    manifest=BACKUPS/(tag+\'.manifest.json\')\n    stamped=dt.datetime.now(dt.timezone.utc).isoformat(timespec=\'seconds\')\n    m={\'version\':\'R8_ONE_SHOT\',\'state\':\'PREPARED\',\'backup\':str(backup),\'tag\':tag,\n       \'source\':SOURCE,\'created_at\':stamped,\'ledger\':ledger,\'result_seen\':stamped}\n    manifest_write(manifest,m)\n    c=sqlite3.connect(str(DB),timeout=15,isolation_level=None)\n    c.execute(\'PRAGMA busy_timeout=15000\')\n    try:\n        c.execute(\'BEGIN IMMEDIATE\')\n        check=CandidateCollector(c)\n        if check.missing:raise RuntimeError(\'NATIVE_CODE_OR_SCHEMA_CHANGED_AFTER_BACKUP:\'+str(check.missing))\n        for x in ledger:\n            check.current_league=x[\'league\']\n            old=row_state(c,x[\'forecast_id\'])\n            if old!=x[\'original\']:\n                raise RuntimeError(\'LIVE_ROW_CHANGED_AFTER_AUDIT:\'+str(x[\'forecast_id\']))\n            check_conflicting_existing(c,x)\n            t={\'id\':x[\'fixture\'],\'league\':x[\'league\'],\'home\':x[\'home\'],\'away\':x[\'away\'],\'date\':x[\'event_date\']}\n            ep={\'hs\':x[\'hs\'],\'as\':x[\'as\'],\'event_id\':x[\'espn_event_id\'],\'kickoff_utc\':x[\'espn_kickoff_utc\']}\n            args=(old[\'forecast_id\'],old[\'root_id\'],old[\'market\'],old[\'selection\'],old[\'odds\'],old[\'stake\'],\n                  old[\'quote_key\'],old[\'quote_at\'],old[\'registered_at\'],old[\'kickoff_utc\'],t,ep)\n            outcome=check._check_one(*args)\n            if outcome[0]!=\'OK\' or outcome[1]!=x[\'status\'] or abs(outcome[2]-x[\'profit\'])>1e-7:\n                raise RuntimeError(\'QUOTE_OR_NATIVE_OUTCOME_CHANGED_IN_TRANSACTION:\'+str(old[\'forecast_id\'])+\':\'+str(outcome[0]))\n        for x in ledger:\n            result=c.execute(\'\'\'UPDATE v55_paper SET status=?,result_home=?,result_away=?,\n              result_seen=?,settled_at=?,profit=?,source=?\n              WHERE forecast_id=? AND status=\'PENDING\' \'\'\',\n              (x[\'status\'],x[\'hs\'],x[\'as\'],stamped,stamped,x[\'profit\'],SOURCE,x[\'forecast_id\']))\n            if result.rowcount!=1:raise RuntimeError(\'NON_ATOMIC_UPDATE_ROWCOUNT\')\n        c.execute(\'\'\'INSERT INTO v55_settlement_runs(checked_at,checked,settled,outcomes_unavailable,report)\n            VALUES(?,?,?,?,?)\'\'\',(stamped,len(ledger),len(ledger),0,json.dumps({\n            \'state\':\'EVA_R8_ESPN_CSV_VERIFIED\',\'tag\':tag,\'settled_now\':len(ledger),\n            \'outcomes\':dict(__import__(\'collections\').Counter(x[\'status\'] for x in ledger)),\n            \'real_orders\':0,\'source\':\'ESPN_FINAL_PLUS_FOOTBALLDATA_FINAL_EXACT_HISTORY\',\n            \'provenance\':\'EXACT_SOURCE_SNAPSHOT_AND_ORIGINAL_FORECAST\'},sort_keys=True)))\n        c.execute(\'COMMIT\')\n    except Exception:\n        if c.in_transaction:c.execute(\'ROLLBACK\')\n        raise\n    finally:c.close()\n    # Manifest has been prewritten; mark committed only after transaction.\n    m[\'state\']=\'APPLIED\'\n    manifest_write(manifest,m)\n    verify=sqlite3.connect(f\'file:{DB}?mode=ro\',uri=True,timeout=20)\n    try:\n        changed=0\n        for x in ledger:\n            now=row_state(verify,x[\'forecast_id\'])\n            if not now or now[\'status\']!=x[\'status\'] or now[\'source\']!=SOURCE or now[\'settled_at\']!=stamped:\n                raise RuntimeError(\'POST_VERIFY_MISMATCH:\'+str(x[\'forecast_id\']))\n            changed+=1\n    finally:verify.close()\n    msg(\'EVA_R8_APPLIED_VERIFIED\',{\'changed\':changed,\'manifest\':str(manifest),\n        \'backup\':str(backup),\'outcomes\':dict(__import__(\'collections\').Counter(x[\'status\'] for x in ledger)),\n        \'net_usd\':round(sum(x[\'profit\'] for x in ledger),4),\'real_orders\':0,\n        \'original_code_changed\':False})\n    return {\'state\':\'APPLIED\',\'changed\':changed}\n\n\ndef guarded_rollback():\n    manifests=sorted(BACKUPS.glob(\'eva_r8_*.manifest.json\'),key=lambda p:p.stat().st_mtime,reverse=True)\n    if not manifests:raise RuntimeError(\'NO_R8_MANIFEST_FOR_ROLLBACK\')\n    chosen=None\n    for path in manifests:\n        x=json.loads(path.read_text(encoding=\'utf-8\'))\n        if x.get(\'version\')!=\'R8_ONE_SHOT\' or x.get(\'source\')!=SOURCE:continue\n        if x.get(\'state\') in (\'APPLIED\',\'ROLLED_BACK\'):\n            chosen=(path,x);break\n        if x.get(\'state\')==\'PREPARED\':\n            # Recovery from interrupted SSH after COMMIT but before APPLIED manifest.\n            # If all rows exactly equal this manifest\'s committed state, safe to undo.\n            con=sqlite3.connect(f\'file:{DB}?mode=ro\',uri=True,timeout=15)\n            try:\n                if x.get(\'ledger\') and all(\n                    (r:=row_state(con,y[\'forecast_id\'])) and r[\'status\']==y[\'status\']\n                    and r[\'source\']==SOURCE and r[\'settled_at\']==x[\'result_seen\']\n                    and r[\'profit\']==y[\'profit\'] and r[\'result_home\']==y[\'hs\']\n                    and r[\'result_away\']==y[\'as\'] for y in x[\'ledger\']):\n                    chosen=(path,x);break\n            finally:con.close()\n    if not chosen:raise RuntimeError(\'NO_APPLIED_R8_MANIFEST_TO_ROLL_BACK\')\n    path,m=chosen\n    if m.get(\'version\')!=\'R8_ONE_SHOT\' or m.get(\'source\')!=SOURCE:\n        raise RuntimeError(\'INVALID_R8_MANIFEST\')\n    if m.get(\'state\')==\'ROLLED_BACK\':\n        msg(\'EVA_R8_ALREADY_ROLLED_BACK\',{\'manifest\':str(path)})\n        return\n    ledger=m[\'ledger\'];stamped=m[\'result_seen\']\n    c=sqlite3.connect(str(DB),timeout=15,isolation_level=None)\n    c.execute(\'PRAGMA busy_timeout=15000\')\n    try:\n        c.execute(\'BEGIN IMMEDIATE\')\n        for x in ledger:\n            current=row_state(c,x[\'forecast_id\'])\n            if (not current or current[\'status\']!=x[\'status\'] or current[\'source\']!=SOURCE\n                or current[\'settled_at\']!=stamped or current[\'profit\']!=x[\'profit\']\n                or current[\'result_home\']!=x[\'hs\'] or current[\'result_away\']!=x[\'as\']):\n                raise RuntimeError(\'ROLLBACK_ROW_CHANGED_REFUSE:\'+str(x[\'forecast_id\']))\n        for x in ledger:\n            old=x[\'original\']\n            p=[old[z] for z in OUTCOME_COLS]+[x[\'forecast_id\']]\n            q=\'UPDATE v55_paper SET \'+\',\'.join(k+\'=?\' for k in OUTCOME_COLS)+\' WHERE forecast_id=?\'\n            if c.execute(q,p).rowcount!=1:raise RuntimeError(\'ROLLBACK_ROWCOUNT_FAILED\')\n        c.execute(\'\'\'INSERT INTO v55_settlement_runs(checked_at,checked,settled,outcomes_unavailable,report)\n                 VALUES(?,?,?,?,?)\'\'\',(dt.datetime.now(dt.timezone.utc).isoformat(timespec=\'seconds\'),\n                  len(ledger),0,len(ledger),json.dumps({\'state\':\'EVA_R8_REVERSAL\',\'tag\':m[\'tag\'],\n                     \'reverted\':len(ledger),\'real_orders\':0})))\n        c.execute(\'COMMIT\')\n    except Exception:\n        if c.in_transaction:c.execute(\'ROLLBACK\')\n        raise\n    finally:c.close()\n    m[\'state\']=\'ROLLED_BACK\'\n    manifest_write(path,m)\n    msg(\'EVA_R8_ROLLBACK_VERIFIED\',{\'changed\':len(ledger),\'manifest\':str(path),\n         \'backup_preserved\':m[\'backup\'],\'real_orders\':0})\n\n\ndef main():\n    validate_target()\n    mode=os.environ[\'EVA_RUN_MODE\']\n    if mode==\'rollback\':guarded_rollback();return\n    ro=sqlite3.connect(f\'file:{DB}?mode=ro\',uri=True,timeout=30)\n    ro.execute(\'PRAGMA query_only=ON\')\n    try:ledger=collect_candidates(ro)\n    finally:ro.close()\n    guarded_apply(ledger)\n\nif __name__==\'__main__\':\n    try:main()\n    except Exception as ex:\n        msg(\'EVA_R8_ABORTED\',{\'reason\':type(ex).__name__+\': \'+str(ex)[:350],\n           \'note\':\'Do not rerun blindly; no automatic source-code changes performed.\'})\n        sys.exit(1)\n', 'r8_runner_legacy.py', 'exec'), module.__dict__)
