exec(compile('#!/usr/bin/env python3\n"""ORACLE EVA R9: full PENDING census + multi-source settlement, paper-only.\n\nR9 never alters predictions, quoted odds, data sources, or native algorithms.\nEvery pending paper forecast is inspected and classified; only exact-provider,\npre-kickoff, confirmed-two-source football records enter a guarded settlement.\n"""\nfrom __future__ import annotations\nimport collections\nimport csv\nimport io\nimport urllib.request\nfrom urllib.parse import urlsplit\nimport datetime as dt\nimport hashlib\nimport json\nimport os\nimport pathlib\nimport re\nimport sqlite3\nimport sys\nimport time\nimport uuid\nfrom typing import Any\nimport r8_runner_legacy as r8\n\nA = r8.a\nUTC = dt.timezone.utc\nDB = pathlib.Path(\'/data/oracle.sqlite3\')\nBACKUPS = pathlib.Path(\'/data/eva-backups\')\nREPORTS = pathlib.Path(\'/data/eva-reports\')\nSOURCE = \'EVA_R10_TWO_INDEPENDENT_FINAL_EXACT_ORIGINAL_QUOTE\'\nVERSION = \'EVA_R10_RECONCILIATION_ONE_SHOT\'\nSCORE_COLS = (\'status\',\'result_home\',\'result_away\',\'result_seen\',\'settled_at\',\'profit\',\'source\')\nLEAGUES = dict(A.DIVS)\nLEAGUES.update({\'de.2\': (\'D2\',\'ger.2\'), \'tr.1\': (\'T1\',\'tur.1\')})\nALLOWED_ORIGINS = {\'sf_forecasts\', \'v58_brain\'}\nMAX_REQUESTS = 200\n\n\ndef emit(name, value):\n    print(name + \' \' + json.dumps(value, ensure_ascii=False, sort_keys=True, default=str), flush=True)\n\n\ndef now_utc():\n    return dt.datetime.now(UTC)\n\n\ndef timestamp():\n    return now_utc().isoformat(timespec=\'seconds\')\n\n\ndef sha8(value):\n    return hashlib.sha256(str(value).encode(\'utf-8\')).hexdigest()[:12]\n\n\ndef columns(c, table):\n    if not re.fullmatch(r\'[A-Za-z_][A-Za-z_0-9]*\',table):return set()\n    return {x[1] for x in c.execute(\'PRAGMA table_info("\'+table+\'")\')}\n\n\ndef table(c, name):\n    return c.execute("SELECT 1 FROM sqlite_master WHERE type=\'table\' AND name=?",(name,)).fetchone() is not None\n\n\ndef pick_league(label):\n    s=str(label or \'\').casefold()\n    if \'бундеслига 2\' in s or \'bundesliga 2\' in s:return \'de.2\'\n    if \'бундеслига\' in s or \'bundesliga\' in s:return \'de.1\'\n    if \'италия\' in s and (\'серия а\' in s or \'serie a\' in s):return \'it.1\'\n    if \'франция\' in s and (\'лига 1\' in s or \'ligue 1\' in s):return \'fr.1\'\n    if \'англия\' in s and (\'премьер\' in s or \'premier\' in s):return \'en.1\'\n    if \'испания\' in s and (\'примера\' in s or \'laliga\' in s):return \'es.1\'\n    if \'нидерланды\' in s and (\'премьер\' in s or \'эредивизи\' in s):return \'nl.1\'\n    if \'португалия\' in s and (\'премьер\' in s or \'примейра\' in s):return \'pt.1\'\n    if \'турция\' in s and (\'супер\' in s or \'super\' in s):return \'tr.1\'\n    return None\n\n\ndef season_for(d):\n    year=d.year if d.month>=7 else d.year-1\n    return f\'{year}-{(year+1)%100:02d}\'\n\n\ndef safe_date(s):\n    try:return dt.date.fromisoformat(str(s)[:10])\n    except (ValueError,TypeError):return None\n\n\ndef read_papers(c, now):\n    if not table(c,\'v55_paper\'):raise RuntimeError(\'PAPER_TABLE_MISSING\')\n    req=set(r8.PAPER_COLS)\n    if not req.issubset(columns(c,\'v55_paper\')):raise RuntimeError(\'MISSING_PAPER_SCHEMA\')\n    rows=c.execute(\'SELECT \'+\',\'.join(r8.PAPER_COLS)+\' FROM v55_paper WHERE status=? ORDER BY kickoff_utc,forecast_id\',(\'PENDING\',)).fetchall()\n    if len(set(x[0] for x in rows))!=len(rows):raise RuntimeError(\'NON_UNIQUE_PAPER_FORECAST_ID\')\n    inventory={}\n    for row in rows:\n        p=dict(zip(r8.PAPER_COLS,row))\n        k=A.clock(p.get(\'kickoff_utc\'))\n        category=\'INVALID_KICKOFF\' if not k else (\'NOT_YET_DUE\' if k>=now else \'PENDING_NO_VERIFIED_RESULT\')\n        inventory[p[\'forecast_id\']]={\'paper\':p,\'reason\':category,\'evidence\':{},\'origin\':p[\'origin\']}\n    return inventory\n\n\ndef inventory_targets(c, inventory):\n    candidates={k:v for k,v in inventory.items() if v[\'reason\']==\'PENDING_NO_VERIFIED_RESULT\'}\n    # Primary corpus: original OpenFootball football fixtures and nflverse fixtures.\n    targets={}\n    sf_ids=sorted({v[\'paper\'][\'original_event_id\'] for v in candidates.values() if v[\'origin\']==\'sf_forecasts\'})\n    matches={}\n    if table(c,\'sf_matches\'):\n        needed={\'id\',\'sport\',\'league\',\'season\',\'match_date\',\'home\',\'away\',\'home_score\',\'away_score\',\'source\'}\n        if needed.issubset(columns(c,\'sf_matches\')):\n            for event_id in sf_ids:\n                found=c.execute(\'SELECT id,sport,league,season,match_date,home,away,home_score,away_score,source FROM sf_matches WHERE id=?\',(event_id,)).fetchall()\n                if len(found)==1:matches[event_id]=dict(zip((\'id\',\'sport\',\'league\',\'season\',\'date\',\'home\',\'away\',\'hs\',\'as\',\'source\'),found[0]))\n    for item in candidates.values():\n        p=item[\'paper\'];eid=p[\'original_event_id\']\n        if item[\'origin\']==\'sf_forecasts\':\n            s=matches.get(eid)\n            if not s:\n                item[\'reason\']=\'SF_FIXTURE_NOT_FOUND_OR_AMBIGUOUS\';continue\n            if s[\'sport\']==\'football\' and s[\'league\'] in LEAGUES and safe_date(s[\'date\']):\n                targets[eid]={\'id\':eid,\'origin\':\'sf_forecasts\',\'league\':s[\'league\'],\n                   \'season\':s[\'season\'],\'date\':safe_date(s[\'date\']),\'home\':s[\'home\'],\'away\':s[\'away\'],\n                   \'stored_home\':s[\'hs\'],\'stored_away\':s[\'as\'],\'stored_source\':s[\'source\']}\n            elif s[\'league\']==\'nfl\' or \'nfl\' in str(s[\'sport\']).casefold() or \'americanfootball\' in str(s[\'sport\']).casefold():\n                item[\'reason\']=\'NFL_TWO_SOURCE_FINAL_REQUIRED\'\n            else:item[\'reason\']=\'SF_UNSUPPORTED_LEAGUE_OR_SPORT\'\n        elif item[\'origin\']==\'v58_brain\':\n            root=str(eid).split(\'|\',1)[1] if str(eid).startswith(\'v58|\') else None\n            if not root or not table(c,\'v5_catalog\'):\n                item[\'reason\']=\'V58_ORIGINAL_ID_OR_CATALOG_MISSING\';continue\n            found=c.execute(\'SELECT root_id,sport,league,kickoff_utc,home,away FROM v5_catalog WHERE root_id=?\',(root,)).fetchall()\n            if len(found)!=1:\n                item[\'reason\']=\'V58_CATALOG_NOT_UNIQUE\';continue\n            root_id,sport,league,kick,home,away=found[0]\n            target_league=pick_league(league)\n            if sport!=\'football\':\n                item[\'reason\']=\'V58_NON_FOOTBALL_NEEDS_SPORT_RULES\';continue\n            if not target_league or target_league not in LEAGUES:\n                item[\'reason\']=\'V58_LEAGUE_NOT_MAPPED\';continue\n            if not A.clock(kick) or not home or not away:\n                item[\'reason\']=\'V58_EVENT_IDENTITY_INCOMPLETE\';continue\n            if abs((A.clock(kick)-A.clock(p[\'kickoff_utc\'])).total_seconds())>600:\n                item[\'reason\']=\'V58_CATALOG_KICKOFF_MISMATCH\';continue\n            targets[eid]={\'id\':eid,\'origin\':\'v58_brain\',\'league\':target_league,\n                 \'season\':season_for(A.clock(kick).date()),\'date\':A.clock(kick).date(),\n                 \'home\':home,\'away\':away,\'root\':root_id,\'catalog_league\':league,\n                 \'stored_home\':None,\'stored_away\':None,\'stored_source\':None}\n        elif item[\'origin\'] in (\'v4_sport_preds\',\'sb_independent_forecasts\'):\n            item[\'reason\']=\'V4_OR_SB_REQUIRES_ORIGINAL_FINAL_AND_QUOTE_PROOF\'\n        else:item[\'reason\']=\'ORIGIN_NOT_AUTOMATABLE\'\n    return targets, matches\n\n\ndef parse_openfootball(raw):\n    obj=json.loads(raw)\n    ans=[]\n    if not isinstance(obj,dict):return ans\n    for match in obj.get(\'matches\',[]):\n        if not isinstance(match,dict):continue\n        score=match.get(\'score\')\n        if not isinstance(score,dict):continue\n        ft=score.get(\'ft\')\n        if not isinstance(ft,list) or len(ft)!=2 or any(isinstance(z,bool) or not isinstance(z,int) or z<0 or z>40 for z in ft):continue\n        when=safe_date(match.get(\'date\'))\n        if not when:continue\n        home=match.get(\'team1\');away=match.get(\'team2\')\n        if not home or not away:continue\n        ans.append({\'date\':when,\'home\':home,\'away\':away,\'hs\':ft[0],\'as\':ft[1]})\n    return ans\n\n\ndef safe_public_data_fetch(url, timeout=12):\n    """No redirects. Two fixed, public read-only GitHub datasets only."""\n    u=urlsplit(url)\n    if (u.scheme!=\'https\' or u.hostname!=\'raw.githubusercontent.com\' or\n        u.port not in (None,443) or u.username or u.password or u.fragment or u.query or\n        not (re.fullmatch(r\'/openfootball/football\\.json/master/20\\d\\d-\\d\\d/[a-z]{2}\\.\\d\\.json\',u.path)\n          or u.path==\'/nflverse/nfldata/master/data/games.csv\')):\n        raise ValueError(\'PUBLIC_SOURCE_URL_NOT_ALLOWED\')\n    class DenyRedirect(urllib.request.HTTPRedirectHandler):\n        def redirect_request(self,*args,**kwargs):\n            raise ValueError(\'PUBLIC_SOURCE_REDIRECT_REFUSED\')\n    req=urllib.request.Request(url,headers={\'User-Agent\':\'EVA-R9-PaperAudit/1.0\',\'Accept\':\'application/json,text/csv\'})\n    with urllib.request.build_opener(DenyRedirect()).open(req,timeout=timeout) as r:\n        if r.status!=200 or r.geturl()!=url:raise ValueError(\'PUBLIC_SOURCE_RESPONSE_CHANGED\')\n        raw=r.read(4_000_001)\n        if len(raw)>4_000_000:raise ValueError(\'PUBLIC_SOURCE_TOO_LARGE\')\n        return raw\n\n\ndef download(url, fetcher=None):\n    if fetcher is not None:return fetcher(url)\n    if urlsplit(url).hostname==\'raw.githubusercontent.com\':return safe_public_data_fetch(url)\n    return A.fetch(url)\n\n\ndef provider_download(targets, fetcher=None, cap=MAX_REQUESTS):\n    all_targets=[t for t in targets.values() if t[\'league\'] in LEAGUES]\n    groups={(t[\'league\'],t[\'season\']) for t in all_targets if re.fullmatch(r\'20\\d\\d-\\d\\d\',str(t[\'season\']))}\n    dates={(t[\'league\'],t[\'date\']+dt.timedelta(days=diff))\n           for t in all_targets for diff in (-1,0,1)\n           if t[\'date\']+dt.timedelta(days=diff)<=now_utc().date()}\n    csv={}; espn={}; openf={}; failures=[]; calls=0\n    # Prioritize match-specific ESPN and CSV over OpenFootball, which can be stale.\n    for lg,season in sorted(groups):\n        code=season[2:4]+season[5:7]\n        base=\'https://www.football-data.co.uk/mmz4281/\'+code+\'/\'+LEAGUES[lg][0]+\'.csv\'\n        if calls>=cap:failures.append([\'csv\',lg,\'request_cap\']);continue\n        try:calls+=1;csv[lg,season]=A.csv_rows(download(base,fetcher))\n        except Exception as ex:failures.append([\'csv\',lg,type(ex).__name__+\':\'+str(ex)[:120]]);csv[lg,season]=[]\n    for lg,day in sorted(dates):\n        if calls>=cap:failures.append([\'espn\',lg,\'request_cap\']);continue\n        url=f\'https://site.api.espn.com/apis/site/v2/sports/soccer/{LEAGUES[lg][1]}/scoreboard?dates={day:%Y%m%d}&limit=150\'\n        try:calls+=1;espn[lg,day]=A.espn_rows(download(url,fetcher))\n        except Exception as ex:failures.append([\'espn\',lg,str(day)+\':\'+type(ex).__name__+\':\'+str(ex)[:120]]);espn[lg,day]=[]\n    for lg,season in sorted(groups):\n        url=f\'https://raw.githubusercontent.com/openfootball/football.json/master/{season}/{lg}.json\'\n        if calls>=cap:failures.append([\'openfootball\',lg,\'request_cap\']);continue\n        try:calls+=1;openf[lg,season]=parse_openfootball(download(url,fetcher))\n        except Exception as ex:failures.append([\'openfootball\',lg,type(ex).__name__+\':\'+str(ex)[:120]]);openf[lg,season]=[]\n    return {\'csv\':csv,\'espn\':espn,\'openfootball\':openf,\'errors\':failures,\'requests\':calls,\n            \'csv_groups\':len(groups),\'espn_date_groups\':len(dates),\'of_groups\':len(groups)}\n\n\ndef evidence_for(t, provider):\n    league=t[\'league\'];day=t[\'date\'];season=t[\'season\']\n    pool=[]\n    for shift in (-1,0,1):pool.extend(provider[\'espn\'].get((league,day+dt.timedelta(days=shift)),[]))\n    espn=A.pick(t,pool)\n    csv=A.pick(t,provider[\'csv\'].get((league,season),[]))\n    openf=A.pick(t,provider[\'openfootball\'].get((league,season),[]))\n    found={\'espn\':espn,\'football_data\':csv,\'openfootball\':openf}\n    if any(x and x.get(\'error\') for x in found.values()):return {\'state\':\'AMBIGUOUS_PROVIDER_IDENTITY\',\'providers\':found}\n    scored={s:(p[\'hs\'],p[\'as\']) for s,p in found.items() if p and \'hs\' in p}\n    if not scored:return {\'state\':\'NO_PROVIDER_FINAL\',\'providers\':found}\n    if len(set(scored.values()))>1:return {\'state\':\'SOURCE_CONFLICT\',\'providers\':found}\n    if not espn:return {\'state\':\'NO_ESPN_FINAL_KICKOFF\',\'providers\':found}\n    independent=int(\'football_data\' in scored)+int(\'openfootball\' in scored)\n    if independent==0:return {\'state\':\'ESPN_ONLY\',\'providers\':found}\n    return {\'state\':\'TWO_SOURCE_AGREEMENT\',\'providers\':found,\'score\':next(iter(scored.values())),\n            \'sources\':sorted(scored)}\n\n\ndef conflict_with_existing(c, t, home,away):\n    old=c.execute(\'\'\'SELECT COUNT(*) FROM v55_paper WHERE origin=? AND original_event_id=?\n          AND status IN (\'WIN\',\'LOSS\',\'PUSH\') AND result_home IS NOT NULL AND result_away IS NOT NULL\n          AND (result_home!=? OR result_away!=?)\'\'\',(t[\'origin\'],t[\'id\'],home,away)).fetchone()[0]\n    if old:return \'CONFLICT_WITH_EXISTING_SETTLED_PAPER\'\n    if t[\'origin\']==\'sf_forecasts\':\n        s=c.execute(\'SELECT home_score,away_score FROM sf_matches WHERE id=?\',(t[\'id\'],)).fetchone()\n        if not s or (s[0] is None)!=(s[1] is None):return \'SF_STORED_SCORE_INCOMPLETE\'\n        if s[0] is not None and (s[0],s[1])!=(home,away):return \'CONFLICT_WITH_SF_STORED_FINAL\'\n    return None\n\n\ndef evaluate_target(c, t, proof, items, inventory, collector, audit_now):\n    if proof[\'state\']!=\'TWO_SOURCE_AGREEMENT\':\n        for v in items:v[\'reason\']=proof[\'state\']\n        return []\n    es=proof[\'providers\'][\'espn\']\n    hs,aw=proof[\'score\']\n    event=A.utc_stamp(es.get(\'kickoff_utc\'))\n    if event is None or audit_now < event+dt.timedelta(minutes=95) or not str(es.get(\'event_id\',\'\')).isdigit():\n        for v in items:v[\'reason\']=\'FINAL_EVENT_TIME_OR_ID_INVALID\'\n        return []\n    if abs((es[\'date\']-t[\'date\']).days)>1:\n        for v in items:v[\'reason\']=\'MATCH_DATE_MISMATCH\'\n        return []\n    existing=conflict_with_existing(c,t,hs,aw)\n    if existing:\n        for v in items:v[\'reason\']=existing\n        return []\n    new=[]\n    for v in items:\n        p=v[\'paper\']\n        kick=A.clock(p[\'kickoff_utc\'])\n        if kick is None or abs((event-kick).total_seconds())>600:\n            v[\'reason\']=\'KICKOFF_MISMATCH_OVER_10_MIN\';continue\n        q=A.clock(p[\'quote_at\']);r=A.clock(p[\'registered_at\'])\n        if q is None or r is None or not q<r<kick:\n            v[\'reason\']=\'NOT_A_VALID_PREKICKOFF_PAPER_BET\';continue\n        if t[\'origin\']==\'v58_brain\' and str(p[\'root_id\'])!=str(t[\'root\']):\n            v[\'reason\']=\'V58_FONBET_ROOT_ID_MISMATCH\';continue\n        collector.current_league=t[\'league\']\n        verdict=collector._check_one(p[\'forecast_id\'],p[\'root_id\'],p[\'market\'],p[\'selection\'],p[\'odds\'],p[\'stake\'],p[\'quote_key\'],p[\'quote_at\'],p[\'registered_at\'],p[\'kickoff_utc\'],t,es)\n        if verdict[0]!=\'OK\':\n            v[\'reason\']=str(verdict[0]);continue\n        outcome,profit=verdict[1:]\n        x=collector.ledger[-1]\n        if x[\'forecast_id\']!=p[\'forecast_id\'] or x[\'status\']!=outcome or abs(x[\'profit\']-profit)>1e-7:\n            raise RuntimeError(\'LEDGER_NOT_ASSOCIATED_WITH_CHECKED_ROW\')\n        x[\'source_consensus\']=proof[\'sources\']\n        x[\'origin\']=t[\'origin\']\n        v[\'reason\']=\'R9_READY_FOR_ATOMIC_SETTLEMENT\'\n        v[\'evidence\']={\'providers\':proof[\'sources\'],\'score\':[hs,aw],\'espn_id\':es[\'event_id\']}\n        new.append(x)\n    return new\n\n\nNFL_TEAM_NAMES = {\n \'ARI\':\'Arizona Cardinals\',\'ATL\':\'Atlanta Falcons\',\'BAL\':\'Baltimore Ravens\',\n \'BUF\':\'Buffalo Bills\',\'CAR\':\'Carolina Panthers\',\'CHI\':\'Chicago Bears\',\n \'CIN\':\'Cincinnati Bengals\',\'CLE\':\'Cleveland Browns\',\'DAL\':\'Dallas Cowboys\',\n \'DEN\':\'Denver Broncos\',\'DET\':\'Detroit Lions\',\'GB\':\'Green Bay Packers\',\n \'HOU\':\'Houston Texans\',\'IND\':\'Indianapolis Colts\',\'JAX\':\'Jacksonville Jaguars\',\n \'KC\':\'Kansas City Chiefs\',\'LA\':\'Los Angeles Rams\',\'LAC\':\'Los Angeles Chargers\',\n \'LV\':\'Las Vegas Raiders\',\'MIA\':\'Miami Dolphins\',\'MIN\':\'Minnesota Vikings\',\n \'NE\':\'New England Patriots\',\'NO\':\'New Orleans Saints\',\'NYG\':\'New York Giants\',\n \'NYJ\':\'New York Jets\',\'PHI\':\'Philadelphia Eagles\',\'PIT\':\'Pittsburgh Steelers\',\n \'SEA\':\'Seattle Seahawks\',\'SF\':\'San Francisco 49ers\',\'TB\':\'Tampa Bay Buccaneers\',\n \'TEN\':\'Tennessee Titans\',\'WAS\':\'Washington Commanders\'\n}\n\n\ndef parse_nflverse_csv(raw):\n    out=[]\n    rows=csv.DictReader(io.StringIO(raw.decode(\'utf-8-sig\', errors=\'replace\')))\n    for r in rows:\n        if r.get(\'season\')!=\'2026\' or not (r.get(\'home_score\') and r.get(\'away_score\')):continue\n        if not (r[\'home_score\'].isdigit() and r[\'away_score\'].isdigit()):continue\n        home=NFL_TEAM_NAMES.get(r.get(\'home_team\'));away=NFL_TEAM_NAMES.get(r.get(\'away_team\'))\n        date=safe_date(r.get(\'gameday\'))\n        if not home or not away or not date:continue\n        hs=int(r[\'home_score\']);aw=int(r[\'away_score\'])\n        if not 0<=hs<=250 or not 0<=aw<=250:continue\n        eid=r.get(\'espn\') or r.get(\'espn_id\') or \'\'\n        out.append({\'date\':date,\'home\':home,\'away\':away,\'hs\':hs,\'as\':aw,\'espn_event_id\':str(eid)})\n    return out\n\n\ndef nfl_observations(c, inventory, matches, fetcher=None):\n    # ESPN + independently stored NFLVerse game scores: audit only.\n    # Native soccer market/quote semantics must not be transferred to NFL.\n    entries=[v for v in inventory.values() if v[\'reason\']==\'NFL_TWO_SOURCE_FINAL_REQUIRED\']\n    if not entries:return {\'bets_examined\':0,\'two_provider_agreements\':0,\'single_source_finals\':0,\'errors\':[]}\n    dates=sorted({safe_date(matches[v[\'paper\'][\'original_event_id\']][\'date\']) for v in entries\n                  if v[\'paper\'][\'original_event_id\'] in matches and safe_date(matches[v[\'paper\'][\'original_event_id\']][\'date\'])})\n    days={date+dt.timedelta(days=delta) for date in dates for delta in (-1,0,1)}\n    events=[];errors=[]\n    for date in sorted(days)[:45]:\n        url=f\'https://site.api.espn.com/apis/site/v2/sports/football/nfl/scoreboard?dates={date:%Y%m%d}&limit=150\'\n        try:\n            raw=json.loads(download(url,fetcher))\n            for ev in raw.get(\'events\',[]):\n                state=(ev.get(\'status\') or {}).get(\'type\') or {}\n                if state.get(\'completed\') is not True or state.get(\'state\')!=\'post\':continue\n                co=(ev.get(\'competitions\') or [{}])[0];sides={}\n                for person in co.get(\'competitors\',[]):\n                    side=person.get(\'homeAway\');team=person.get(\'team\') or {}\n                    try:score=int(person[\'score\'])\n                    except (ValueError,TypeError,KeyError):continue\n                    if side in (\'home\',\'away\') and 0<=score<=250:sides[side]=(team.get(\'displayName\') or \'\',score)\n                if set(sides)=={\'home\',\'away\'}:\n                    events.append({\'date\':safe_date(ev.get(\'date\')),\'home\':sides[\'home\'][0],\n                                   \'away\':sides[\'away\'][0],\'hs\':sides[\'home\'][1],\'as\':sides[\'away\'][1],\n                                   \'event_id\':str(ev.get(\'id\',\'\'))})\n        except Exception as ex:errors.append(\'ESPN_NFL:\'+type(ex).__name__+\':\'+str(ex)[:70])\n    csv_results=[]\n    try:\n        csv_results=parse_nflverse_csv(download(\n           \'https://raw.githubusercontent.com/nflverse/nfldata/master/data/games.csv\',fetcher))\n    except Exception as ex:errors.append(\'NFLVERSE:\'+type(ex).__name__+\':\'+str(ex)[:70])\n    verified=single=conflict=0\n    for v in entries:\n        s=matches.get(v[\'paper\'][\'original_event_id\'])\n        if not s:continue\n        t={\'home\':s[\'home\'],\'away\':s[\'away\'],\'date\':safe_date(s[\'date\'])}\n        e=A.pick(t,[z for z in events if z.get(\'date\') is not None])\n        nf=A.pick(t,csv_results)\n        if any(x and x.get(\'error\') for x in (e,nf)):\n            v[\'reason\']=\'NFL_AMBIGUOUS_PROVIDER_MATCH\';continue\n        if e and nf:\n            ids_match=(not nf.get(\'espn_event_id\') or not e.get(\'event_id\') or nf[\'espn_event_id\']==e[\'event_id\'])\n            if (e[\'hs\'],e[\'as\'])==(nf[\'hs\'],nf[\'as\']) and ids_match:\n                verified+=1\n                v[\'reason\']=\'NFL_TWO_SOURCE_SCORE_ONLY_UNSUPPORTED_MARKET_PROVENANCE\'\n                v[\'evidence\']={\'sources\':[\'ESPN_NFL\',\'NFLVERSE_GAMES\'],\'score\':[e[\'hs\'],e[\'as\']]}\n            else:\n                conflict+=1;v[\'reason\']=\'NFL_SOURCE_CONFLICT\'\n        elif e or nf:\n            single+=1;v[\'reason\']=\'NFL_ONE_FINAL_SOURCE_ONLY\'\n            source=e or nf\n            v[\'evidence\']={\'score\':[source[\'hs\'],source[\'as\']],\n                           \'source\':\'ESPN_NFL\' if e else \'NFLVERSE_GAMES\'}\n    return {\'bets_examined\':len(entries),\'two_provider_agreements\':verified,\n            \'single_source_finals\':single,\'source_conflicts\':conflict,\n            \'nflverse_finished_games_2026\':len(csv_results),\'days_requested\':min(45,len(days)),\n            \'errors\':errors[:15],\'auto_settled_nfl\':0}\n\n\ndef settled_pnl_snapshot(c):\n    snap={}\n    for scope,q in [\n       (\'all_paper\',"SELECT COUNT(*),COALESCE(SUM(stake),0),COALESCE(SUM(profit),0) FROM v55_paper WHERE status IN (\'WIN\',\'LOSS\',\'PUSH\')"),\n       (\'selected_portfolio\',"SELECT COUNT(*),COALESCE(SUM(p.stake),0),COALESCE(SUM(p.profit),0) FROM v56_portfolio f JOIN v55_paper p ON p.forecast_id=f.forecast_id WHERE p.status IN (\'WIN\',\'LOSS\',\'PUSH\')")]:\n        if scope==\'selected_portfolio\' and not table(c,\'v56_portfolio\'):\n            snap[scope]={\'status\':\'TABLE_NOT_FOUND\'};continue\n        try:\n            n,stake,profit=c.execute(q).fetchone()\n            snap[scope]={\'settled\':n,\'stake_usd\':round(float(stake),4),\n                          \'net_usd\':round(float(profit),4),\n                          \'roi_pct\':round(float(profit)/float(stake)*100,4) if stake else None}\n        except (sqlite3.Error,TypeError,ValueError,ZeroDivisionError) as exc:\n            snap[scope]={\'status\':\'NOT_READABLE\',\'error\':type(exc).__name__}\n    return snap\n\n\ndef stored_results_audit(c, inventory):\n    """Review already saved V4 and V58 finals as supporting evidence only."""\n    out=collections.Counter()\n    native=None\n    try:\n        if \'/app\' not in sys.path:sys.path.insert(0,\'/app\')\n        import oracle_v5_settlement as native\n    except Exception:pass\n    vr_table=table(c,\'v58_results\')\n    required={\'source_event_id\',\'sport\',\'kickoff_utc\',\'home\',\'away\',\'home_score\',\n              \'away_score\',\'observed_at\',\'final_provenance\'}\n    vr_ok=vr_table and required.issubset(columns(c,\'v58_results\'))\n    if vr_table and not vr_ok:out[\'V58_RESULTS_SCHEMA_UNVERIFIED\']+=1\n    for v in inventory.values():\n        if v[\'reason\'] in (\'NOT_YET_DUE\',\'INVALID_KICKOFF\',\'R9_READY_FOR_ATOMIC_SETTLEMENT\'):continue\n        p=v[\'paper\'];origin=p[\'origin\']\n        if origin in (\'v4_sport_preds\',\'sb_independent_forecasts\'):\n            if not native:\n                out[\'NATIVE_SETTLEMENT_MODULE_NOT_READY\']+=1;continue\n            try:\n                rec=native._resolve_score(c,origin,p[\'original_event_id\'],p[\'kickoff_utc\'],timestamp())\n                if rec:\n                    v[\'reason\']=\'V4_STORED_FINAL_NEEDS_PRICE_AND_INDEPENDENT_SOURCE\'\n                    v[\'evidence\']={\'stored_final_score\':[rec[0],rec[1]],\'source\':rec[3]}\n                    out[\'V4_STORED_FINAL_FOUND\']+=1\n                else:out[\'V4_NO_NATIVE_FINAL\']+=1\n            except Exception:out[\'V4_NATIVE_RESOLVER_ERROR\']+=1\n        elif origin==\'v58_brain\':\n            out[\'V58_CHECKED\']+=1\n            if not vr_ok or not table(c,\'v5_catalog\') or not str(p[\'original_event_id\']).startswith(\'v58|\'):continue\n            root=p[\'original_event_id\'].split(\'|\',1)[1]\n            cat=c.execute(\'SELECT sport,home,away,kickoff_utc FROM v5_catalog WHERE root_id=?\',(root,)).fetchall()\n            if len(cat)!=1:continue\n            sport,home,away,kick=cat[0]\n            if not kick or not home or not away:continue\n            day=safe_date(kick)\n            if day is None:continue\n            lo=(day-dt.timedelta(days=1)).isoformat()\n            hi=(day+dt.timedelta(days=2)).isoformat()\n            possible=c.execute("SELECT source_event_id,kickoff_utc,home,away,home_score,away_score,observed_at,final_provenance FROM v58_results WHERE sport=? AND kickoff_utc>=? AND kickoff_utc<? LIMIT 600",(sport,lo,hi)).fetchall()\n            finals=[]\n            for sid,at,h,a,hs,aw,seen,marker in possible:\n                if marker!=\'SOURCE_MARKED_FINAL\' or hs is None or aw is None:continue\n                if A.namekey(home)!=A.namekey(h) or A.namekey(away)!=A.namekey(a):continue\n                if not A.clock(at) or abs((A.clock(kick)-A.clock(at)).total_seconds())>600:continue\n                finals.append((sid,int(hs),int(aw),seen))\n            if len(finals)==1:\n                sid,hs,aw,seen=finals[0]\n                out[\'V58_STORED_SOURCE_MARKED_FINAL_FOUND\']+=1\n                v[\'evidence\'].setdefault(\'stored_result\',{\'score\':[hs,aw],\n                    \'source_event_sha12\':sha8(sid),\'provider\':\'V58_RESULTS\'})\n                if v[\'reason\'] in (\'NO_PROVIDER_FINAL\',\'ESPN_ONLY\',\'NO_ESPN_FINAL_KICKOFF\'):\n                    v[\'reason\']=\'V58_STORED_FINAL_ONLY_NOT_NEW_INDEPENDENT_SOURCE\'\n            elif len(finals)>1:out[\'V58_MULTIPLE_STORED_FINALS_UNRESOLVED\']+=1\n        elif origin==\'sf_forecasts\':out[\'SF_CHECKED\']+=1\n        else:out[\'UNKNOWN_ORIGIN\']+=1\n    return dict(out)\n\n\ndef supplemental_research_counts(c):\n    data={}\n    if table(c,\'sf_forecasts\') and {\'status\',\'match_id\'}.issubset(columns(c,\'sf_forecasts\')):\n        data[\'sf_research_by_status\']={str(st):int(n) for st,n in\n          c.execute(\'SELECT status,COUNT(*) FROM sf_forecasts GROUP BY status\')}\n    if table(c,\'v56_portfolio\'):\n        data[\'portfolio_rows\']=c.execute(\'SELECT COUNT(*) FROM v56_portfolio\').fetchone()[0]\n        if \'forecast_id\' in columns(c,\'v56_portfolio\'):\n            data[\'portfolio_pending_paper_rows\']=c.execute("SELECT COUNT(*) FROM v56_portfolio x JOIN v55_paper p ON p.forecast_id=x.forecast_id WHERE p.status=\'PENDING\'").fetchone()[0]\n    return data\n\n\ndef census(c, fetcher=None, external=True, limit=MAX_REQUESTS):\n    audit_now=now_utc()\n    inventory=read_papers(c,audit_now)\n    targets,matches=inventory_targets(c,inventory)\n    eligible={k:[] for k in targets}\n    for v in inventory.values():\n        eid=v[\'paper\'][\'original_event_id\']\n        if eid in eligible and v[\'origin\']==targets[eid][\'origin\'] and v[\'reason\']==\'PENDING_NO_VERIFIED_RESULT\':eligible[eid].append(v)\n    provider={\'csv\':{},\'espn\':{},\'openfootball\':{},\'errors\':[],\'requests\':0}\n    if external and eligible:provider=provider_download({k:v for k,v in targets.items() if eligible[k]},fetcher,limit)\n    collector=r8.CandidateCollector(c)\n    if collector.missing:\n        emit(\'EVA_R10_NATIVE_GATE_UNAVAILABLE\',{\'reasons\':collector.missing})\n    ledger=[];event_state=collections.Counter()\n    for event_id,t in sorted(targets.items(),key=lambda x:str(x[0])):\n        items=eligible[event_id]\n        if not items:continue\n        ev=evidence_for(t,provider) if external else {\'state\':\'OFFLINE_READONLY\',\'providers\':{}}\n        event_state[ev[\'state\']]+=1\n        if collector.missing:\n            for v in items:v[\'reason\']=\'NATIVE_GATE_UNAVAILABLE\'\n            continue\n        new=evaluate_target(c,t,ev,items,inventory,collector,audit_now)\n        ledger.extend(new)\n    # R10 supplemental read-only evidence. Do not change gate, reasons, ledger or DB.\n    # Network requests were already made by provider_download in this same census.\n    native=collector.settlement if not collector.missing else None\n    event_evidence={}\n    for event_id,t in targets.items():\n        items=eligible.get(event_id,[])\n        if not items:continue\n        proof=evidence_for(t,provider) if external else {\'state\':\'OFFLINE_READONLY\',\'providers\':{}}\n        ev=source_evidence_snapshot(t,proof)\n        event_evidence[sha8(event_id)]=ev\n        es=(proof.get(\'providers\') or {}).get(\'espn\')\n        source_conflict=None\n        if es and \'hs\' in es and \'as\' in es and proof.get(\'state\') in (\'ESPN_ONLY\',\'TWO_SOURCE_AGREEMENT\'):\n            source_conflict=conflict_with_existing(c,t,int(es[\'hs\']),int(es[\'as\']))\n        for item in items:\n            item[\'research\']=({\'state\':\'STORED_SCORE_CONFLICT\',\'reason\':source_conflict}\n                if source_conflict else research_outcome_snapshot(t,proof,item[\'paper\'],native,audit_now))\n            item[\'evidence\'].setdefault(\'provider_audit\',ev)\n            item[\'evidence\'][\'research_only\']=item[\'research\']\n    research_summary=summarize_research(inventory)\n    future_quality=future_quote_quality(c,inventory)\n    nfl=nfl_observations(c,inventory,matches,fetcher) if external else {\'status\':\'SKIPPED_OFFLINE\'}\n    legacy=stored_results_audit(c,inventory)\n    counts=collections.Counter(v[\'reason\'] for v in inventory.values())\n    status_by_origin=collections.defaultdict(collections.Counter)\n    details=[]\n    for v in inventory.values():\n        p=v[\'paper\'];status_by_origin[str(p[\'origin\'])][v[\'reason\']]+=1\n        details.append({\'forecast_sha12\':sha8(p[\'forecast_id\']), \'origin\':str(p[\'origin\']),\n                        \'original_event_sha12\':sha8(p[\'original_event_id\']),\n                        \'kickoff_utc\':p[\'kickoff_utc\'],\'reason\':v[\'reason\'],\n                        \'market\':p[\'market\'],\'selection\':p[\'selection\'],\n                        \'odds\':p[\'odds\'],\'stake\':p[\'stake\'],\'evidence\':v[\'evidence\']})\n    if sum(counts.values())!=len(inventory):raise RuntimeError(\'INVENTORY_RECONCILIATION_FAILED\')\n    if len({x[\'forecast_id\'] for x in ledger})!=len(ledger):raise RuntimeError(\'DUPLICATE_LEDGER_IDS\')\n    if counts.get(\'R9_READY_FOR_ATOMIC_SETTLEMENT\',0)!=len(ledger):raise RuntimeError(\'LEDGER_CENSUS_MISMATCH\')\n    data={\'version\':VERSION,\'at\':timestamp(),\'pending_total\':len(inventory),\n          \'past_due_count\':sum(1 for v in inventory.values() if v[\'reason\']!=\'NOT_YET_DUE\' and A.clock(v[\'paper\'][\'kickoff_utc\']) and A.clock(v[\'paper\'][\'kickoff_utc\'])<audit_now),\n          \'future_count\':counts.get(\'NOT_YET_DUE\',0),\n          \'reasons\':dict(counts),\'by_origin\':{k:dict(v) for k,v in status_by_origin.items()},\n          \'football_fixtures_checked\':len(eligible),\'football_event_states\':dict(event_state),\n          \'previous_settled_pnl\':settled_pnl_snapshot(c),\n          \'provider_requests\':provider[\'requests\'],\'provider_errors\':provider[\'errors\'],\n          \'nfl\':nfl,\'legacy\':legacy,\'research_and_portfolio\':supplemental_research_counts(c),\n          \'ready_to_settle\':len(ledger),\n          \'preview_outcomes\':dict(collections.Counter(x[\'status\'] for x in ledger)),\n          \'preview_net_usd\':round(sum(x[\'profit\'] for x in ledger),4),\n          \'historical_quote_missing_not_promoted\':counts.get(\'NO_ORIGINAL_PRICE_OBSERVATION\',0),\n          \'details\':details,\'event_evidence\':event_evidence,\n          \'research_only_preview\':research_summary,\n          \'future_quote_quality\':future_quality,\n          \'evidence_missing_legacy_count\':sum(1 for v in inventory.values() if not v[\'evidence\']),\n          \'real_orders\':0,\'source_code_changes\':0}\n    emit(\'EVA_R10_FULL_COVERAGE_SUMMARY\',{k:v for k,v in data.items() if k not in (\'details\',\'event_evidence\')})\n    return data,ledger\n\n\n\ndef source_evidence_snapshot(target, observation):\n    """Non-authoritative source evidence, no interpolated results or event guessing."""\n    providers=observation.get(\'providers\') or {}\n    out={\'event_sha12\':sha8(target[\'id\']),\n         \'league\':target[\'league\'], \'match_date\':str(target[\'date\']),\n         \'home\':target[\'home\'],\'away\':target[\'away\'],\n         \'match_state\':observation[\'state\'],\'providers\':{}}\n    for key in (\'espn\',\'football_data\',\'openfootball\'):\n        p=providers.get(key)\n        if p is None:out[\'providers\'][key]={\'state\':\'NOT_MATCHED\'};continue\n        if p.get(\'error\'):out[\'providers\'][key]={\'state\':\'AMBIGUOUS\',\'error\':str(p[\'error\'])};continue\n        if \'hs\' not in p or \'as\' not in p:out[\'providers\'][key]={\'state\':\'NO_SCORE\'};continue\n        q={\'state\':\'FINAL_SCORE_MATCHED\',\'score\':[int(p[\'hs\']),int(p[\'as\'])],\n           \'date\':str(p.get(\'date\'))}\n        if key==\'espn\':\n            q[\'event_id\']=str(p.get(\'event_id\',\'\'))\n            q[\'kickoff_utc\']=str(p.get(\'kickoff_utc\',\'\'))\n        out[\'providers\'][key]=q\n    return out\n\n\ndef research_outcome_snapshot(target, proof, paper, native, clock_now):\n    """Research-only theoretical outcome, NEVER a settlement authorization.\n\n    Supports final ESPN event alone or two-source consensus, with exact team/date\n    and kickoff identity provided by strict R9 matching. Does not certify quote\n    origin, market mapping to the bookmaker factor, or execution at paper odds.\n    """\n    reason=proof.get(\'state\')\n    if reason not in (\'TWO_SOURCE_AGREEMENT\',\'ESPN_ONLY\'):\n        return {\'state\':\'NO_VALIDATED_ESPN_FINAL\',\'reason\':reason}\n    es=(proof.get(\'providers\') or {}).get(\'espn\')\n    if not es or es.get(\'error\') or not str(es.get(\'event_id\',\'\')).isdigit():\n        return {\'state\':\'ESPN_IDENTITY_NOT_CONFIRMED\'}\n    kickoff=A.utc_stamp(es.get(\'kickoff_utc\'))\n    stake,odds=paper.get(\'stake\'),paper.get(\'odds\')\n    p_kick=A.clock(paper.get(\'kickoff_utc\'))\n    q=A.clock(paper.get(\'quote_at\'))\n    reg=A.clock(paper.get(\'registered_at\'))\n    if not kickoff or not p_kick or abs((kickoff-p_kick).total_seconds())>600:\n        return {\'state\':\'KICKOFF_NOT_CONFIRMED\'}\n    if clock_now<kickoff+dt.timedelta(minutes=95):\n        return {\'state\':\'FINAL_TOO_EARLY\'}\n    if not q or not reg or not q<reg<p_kick:\n        return {\'state\':\'PAPER_TIMESTAMPS_NOT_PREKICKOFF\'}\n    import math\n    if (not isinstance(stake,(int,float)) or isinstance(stake,bool) or not math.isfinite(stake) or stake<=0\n        or not isinstance(odds,(int,float)) or isinstance(odds,bool) or not math.isfinite(odds) or not 1.001<odds<=1001):\n        return {\'state\':\'PAPER_ODDS_OR_STAKE_INVALID\'}\n    if native is None or not callable(getattr(native,\'_market_outcome\',None)):\n        return {\'state\':\'NATIVE_OUTCOME_UNAVAILABLE\'}\n    try:\n        result=native._market_outcome(paper[\'market\'],paper[\'selection\'],int(es[\'hs\']),int(es[\'as\']))\n    except Exception:\n        return {\'state\':\'NATIVE_OUTCOME_ERROR\'}\n    if result not in (\'WIN\',\'LOSS\',\'PUSH\'):\n        return {\'state\':\'UNSUPPORTED_NATIVE_MARKET\'}\n    net=(stake*(odds-1) if result==\'WIN\' else (-stake if result==\'LOSS\' else 0.0))\n    grade=(\'TWO_PROVIDER_SCORES\' if reason==\'TWO_SOURCE_AGREEMENT\' else \'ESPN_FINAL_ONLY\')\n    return {\'state\':\'THEORETICAL_ONLY\',\'grade\':grade, \'outcome\':result,\n            \'theoretical_pnl_usd\':round(float(net),6), \'stake_usd\':float(stake),\n            \'score\':[int(es[\'hs\']),int(es[\'as\'])],\n            \'warning\':\'ODDS_NOT_INDEPENDENTLY_VALIDATED; NOT_OFFICIAL_PNL\'}\n\n\ndef future_quote_quality(c, inventory):\n    """Pre-kickoff capture completeness check, strictly read-only.\n\n    This only diagnoses data that future settlement would need. Never upgrades\n    eligibility or supplies missing historical snapshots.\n    """\n    counts=collections.Counter()\n    for item in inventory.values():\n        if item[\'reason\']!=\'NOT_YET_DUE\':continue\n        p=item[\'paper\'];state=\'UNKNOWN\'\n        try:\n            q=A.clock(p.get(\'quote_at\'));registered=A.clock(p.get(\'registered_at\'))\n            kickoff=A.clock(p.get(\'kickoff_utc\'))\n            if not q or not registered or not kickoff or not q<registered<kickoff:\n                state=\'INVALID_PAPER_TIME_ORDER\'\n            else:\n                rows=c.execute(\'SELECT price,quote_key,quote_snapshot FROM v5_forecasts WHERE id=?\',\n                    (p[\'forecast_id\'],)).fetchall()\n                if len(rows)!=1:state=\'PARENT_NOT_UNIQUE_OR_MISSING\'\n                else:\n                    price,key,at=rows[0]\n                    if (str(key)!=str(p[\'quote_key\']) or A.clock(at)!=q\n                        or price is None or p.get(\'odds\') is None\n                        or abs(float(price)-float(p[\'odds\']))>0.000001):\n                        state=\'PARENT_QUOTE_DISCREPANCY\'\n                    else:\n                        hist=c.execute(\'SELECT decimal_price FROM fb_full_history WHERE quote_key=? AND changed_at=? LIMIT 3\',\n                            (p[\'quote_key\'],p[\'quote_at\'])).fetchall()\n                        if len(hist)!=1:state=\'EXACT_ORIGINAL_HISTORY_MISSING_OR_AMBIGUOUS\'\n                        elif hist[0][0] is None or abs(float(hist[0][0])-float(p[\'odds\']))>0.000001:\n                            state=\'HISTORY_PRICE_MISMATCH\'\n                        else:state=\'EXACT_PARENT_AND_HISTORY_AVAILABLE\'\n        except (sqlite3.Error,ValueError,TypeError,OverflowError):state=\'FUTURE_PROVENANCE_QUERY_ERROR\'\n        item[\'evidence\'][\'future_quote_quality\']=state\n        counts[state]+=1\n    return dict(counts)\n\n\ndef summarize_research(inventory):\n    totals=collections.defaultdict(lambda:{\'rows\':0,\'win\':0,\'loss\':0,\'push\':0,\'stake\':0.0,\'net\':0.0,\'unique_events\':set(),\'unique_market_choices\':set()})\n    states=collections.Counter()\n    for item in inventory.values():\n        r=item.get(\'research\') or {}\n        states[r.get(\'state\',\'NOT_EVALUATED\')]+=1\n        if r.get(\'state\')!=\'THEORETICAL_ONLY\':continue\n        g=r[\'grade\'];t=totals[g];p=item[\'paper\']\n        t[\'rows\']+=1;t[r[\'outcome\'].lower()]+=1;t[\'stake\']+=r[\'stake_usd\'];t[\'net\']+=r[\'theoretical_pnl_usd\']\n        t[\'unique_events\'].add((p[\'origin\'],p[\'original_event_id\']))\n        t[\'unique_market_choices\'].add((p[\'origin\'],p[\'original_event_id\'],p[\'market\'],p[\'selection\']))\n    result={}\n    for grade,t in totals.items():\n        result[grade]={\'rows\':t[\'rows\'],\'outcomes\':{\'WIN\':t[\'win\'],\'LOSS\':t[\'loss\'],\'PUSH\':t[\'push\']},\n            \'stake_usd\':round(t[\'stake\'],4),\'theoretical_net_usd\':round(t[\'net\'],4),\n            \'theoretical_roi_pct\':round(100*t[\'net\']/t[\'stake\'],4) if t[\'stake\'] else None,\n            \'unique_events\':len(t[\'unique_events\']),\n            \'unique_event_market_choices\':len(t[\'unique_market_choices\'])}\n    return {\'by_evidence_grade\':result,\'states\':dict(states),\n            \'WARNING\':\'RESEARCH_ONLY: source final is not proof of executable odds or realized PnL; repeated paper rows are correlated.\'}\n\n\ndef atomic_json(path,obj):\n    payload=json.dumps(obj,ensure_ascii=False,sort_keys=True,indent=2,default=str).encode(\'utf-8\')\n    temp=path.parent/(\'.\'+path.name+\'.\'+uuid.uuid4().hex+\'.tmp\')\n    fd=os.open(temp,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600)\n    try:\n        with os.fdopen(fd,\'wb\') as fp:fp.write(payload);fp.flush();os.fsync(fp.fileno())\n        os.replace(temp,path)\n    except Exception:\n        try:os.unlink(temp)\n        except OSError:pass\n        raise\n\n\ndef online_backup():\n    tag=\'eva_r10_\'+now_utc().strftime(\'%Y%m%dT%H%M%SZ\')+\'_\'+uuid.uuid4().hex[:10]\n    backup=BACKUPS/(tag+\'.sqlite3\')\n    fd=os.open(backup,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600);os.close(fd)\n    try:\n        source=sqlite3.connect(f\'file:{DB}?mode=ro\',uri=True,timeout=30)\n        copy=sqlite3.connect(str(backup),timeout=30)\n        try:source.backup(copy,pages=1024,sleep=.12)\n        finally:copy.close();source.close()\n        check=sqlite3.connect(f\'file:{backup}?mode=ro\',uri=True,timeout=30)\n        try:\n            if check.execute(\'PRAGMA quick_check\').fetchone()[0]!=\'ok\':raise RuntimeError(\'BACKUP_QUICK_CHECK_FAILED\')\n        finally:check.close()\n        emit(\'EVA_R10_BACKUP_OK\',{\'path\':str(backup),\'bytes\':backup.stat().st_size,\'quick_check\':\'ok\'})\n        return backup,tag\n    except Exception:\n        try:backup.rename(str(backup)+\'.incomplete\')\n        except OSError:pass\n        raise\n\n\ndef write_settlement(ledger,report,mode=\'apply\'):\n    if mode!=\'apply\':\n        emit(\'EVA_R10_AUDIT_ONLY\',{\'ready_candidates\':len(ledger),\'writes\':0});return 0\n    if not ledger:\n        emit(\'EVA_R10_NO_CHANGES\',{\'reason\':\'NO_NEW_EXACTLY_PROVEN_PAPER_BETS\'});return 0\n    backup,tag=online_backup()\n    manifest=BACKUPS/(tag+\'.manifest.json\')\n    stamp=timestamp()\n    data={\'version\':VERSION,\'tag\':tag,\'state\':\'PREPARED\',\'source\':SOURCE,\'backup\':str(backup),\n          \'created_at\':stamp,\'ledger\':ledger,\'settled_at\':stamp}\n    atomic_json(manifest,data)\n    c=sqlite3.connect(str(DB),timeout=30,isolation_level=None)\n    c.execute(\'PRAGMA busy_timeout=30000\')\n    try:\n        c.execute(\'BEGIN IMMEDIATE\')\n        checker=r8.CandidateCollector(c)\n        if checker.missing:raise RuntimeError(\'NATIVE_GATE_CHANGED_AFTER_BACKUP\')\n        for x in ledger:\n            orig=r8.row_state(c,x[\'forecast_id\'])\n            if orig!=x[\'original\']:raise RuntimeError(\'LIVE_PAPER_CHANGED_AFTER_AUDIT:\'+sha8(x[\'forecast_id\']))\n            t={\'id\':x[\'fixture\'],\'league\':x[\'league\'],\'date\':x[\'event_date\'],\n               \'home\':x[\'home\'],\'away\':x[\'away\']}\n            ep={\'hs\':x[\'hs\'],\'as\':x[\'as\'],\'event_id\':x[\'espn_event_id\'],\n                \'kickoff_utc\':x[\'espn_kickoff_utc\']}\n            if x[\'origin\']==\'v58_brain\':\n                root=x[\'fixture\'].split(\'|\',1)[1]\n                cat=c.execute(\'SELECT sport,home,away,kickoff_utc FROM v5_catalog WHERE root_id=?\',(root,)).fetchall()\n                if len(cat)!=1 or cat[0][0]!=\'football\' or cat[0][1]!=x[\'home\'] or cat[0][2]!=x[\'away\'] or cat[0][3]!=orig[\'kickoff_utc\']:\n                    raise RuntimeError(\'V58_CATALOG_CHANGED:\'+sha8(root))\n            else:\n                row=c.execute(\'SELECT home_score,away_score,home,away FROM sf_matches WHERE id=?\',(x[\'fixture\'],)).fetchone()\n                if not row or row[2:]!=(x[\'home\'],x[\'away\']) or (row[0] is None)!=(row[1] is None):\n                    raise RuntimeError(\'SF_FIXTURE_CHANGED:\'+sha8(x[\'fixture\']))\n                if row[0] is not None and row[:2]!=(x[\'hs\'],x[\'as\']):\n                    raise RuntimeError(\'SF_CONFLICTING_STORED_SCORE\')\n            con=c.execute(\'\'\'SELECT COUNT(*) FROM v55_paper WHERE origin=? AND original_event_id=?\n                AND status IN (\'WIN\',\'LOSS\',\'PUSH\') AND result_home IS NOT NULL AND result_away IS NOT NULL\n                AND (result_home!=? OR result_away!=?)\'\'\',\n                (x[\'origin\'],x[\'fixture\'],x[\'hs\'],x[\'as\'])).fetchone()[0]\n            if con:raise RuntimeError(\'CONFLICTING_PREEXISTING_SETTLED_SCORE\')\n            checker.current_league=x[\'league\']\n            verdict=checker._check_one(orig[\'forecast_id\'],orig[\'root_id\'],orig[\'market\'],orig[\'selection\'],\n                orig[\'odds\'],orig[\'stake\'],orig[\'quote_key\'],orig[\'quote_at\'],orig[\'registered_at\'],\n                orig[\'kickoff_utc\'],t,ep)\n            if verdict[0]!=\'OK\' or verdict[1]!=x[\'status\'] or abs(verdict[2]-x[\'profit\'])>1e-7:\n                raise RuntimeError(\'QUOTED_ODDS_OR_NATIVE_MARKET_CHANGED:\'+sha8(x[\'forecast_id\']))\n        for x in ledger:\n            result=c.execute(\'\'\'UPDATE v55_paper SET status=?,result_home=?,result_away=?,result_seen=?,\n                     settled_at=?,profit=?,source=? WHERE forecast_id=? AND status=\'PENDING\' \'\'\',\n                   (x[\'status\'],x[\'hs\'],x[\'as\'],stamp,stamp,x[\'profit\'],SOURCE,x[\'forecast_id\']))\n            if result.rowcount!=1:raise RuntimeError(\'NOT_ONE_ROW_UPDATED\')\n        result_report={\'state\':\'EVA_R10_TWO_SOURCE_SETTLED\',\'tag\':tag,\'count\':len(ledger),\n                       \'outcomes\':dict(collections.Counter(x[\'status\'] for x in ledger)),\n                       \'source\':SOURCE,\'real_orders\':0}\n        c.execute(\'\'\'INSERT INTO v55_settlement_runs(checked_at,checked,settled,outcomes_unavailable,report)\n             VALUES(?,?,?,?,?)\'\'\',(stamp,report[\'pending_total\'],len(ledger),report[\'pending_total\']-len(ledger),\n                             json.dumps(result_report,ensure_ascii=False)))\n        c.execute(\'COMMIT\')\n    except Exception:\n        if c.in_transaction:c.execute(\'ROLLBACK\')\n        raise\n    finally:c.close()\n    data[\'state\']=\'APPLIED\';atomic_json(manifest,data)\n    verify=sqlite3.connect(f\'file:{DB}?mode=ro\',uri=True,timeout=30)\n    try:\n        for x in ledger:\n            row=r8.row_state(verify,x[\'forecast_id\'])\n            if not row or row[\'status\']!=x[\'status\'] or row[\'source\']!=SOURCE or row[\'settled_at\']!=stamp or row[\'profit\']!=x[\'profit\']:\n                raise RuntimeError(\'POST_COMMIT_VERIFICATION_FAILED:\'+sha8(x[\'forecast_id\']))\n    finally:verify.close()\n    emit(\'EVA_R10_APPLIED_VERIFIED\',{\'changed\':len(ledger),\'backup\':str(backup),\'manifest\':str(manifest),\n           \'outcomes\':dict(collections.Counter(x[\'status\'] for x in ledger)),\n           \'net_usd\':round(sum(x[\'profit\'] for x in ledger),4),\'production_oracle_changed\':False,\'real_orders\':0})\n    return len(ledger)\n\n\ndef rollback():\n    found=[]\n    for f in BACKUPS.glob(\'eva_r10_*.manifest.json\'):\n        try:\n            x=json.loads(f.read_text(\'utf-8\'))\n            if x.get(\'version\')==VERSION and x.get(\'source\')==SOURCE and x.get(\'state\') in (\'APPLIED\',\'PREPARED\'):\n                found.append((f.stat().st_mtime,f,x))\n        except (OSError,ValueError):continue\n    if not found:raise RuntimeError(\'NO_R9_MANIFEST_FOR_ROLLBACK\')\n    _,path,data=max(found,key=lambda x:x[0])\n    ledger=data[\'ledger\'];stamp=data[\'settled_at\']\n    c=sqlite3.connect(str(DB),timeout=30,isolation_level=None)\n    c.execute(\'PRAGMA busy_timeout=30000\')\n    try:\n        c.execute(\'BEGIN IMMEDIATE\')\n        for x in ledger:\n            old=r8.row_state(c,x[\'forecast_id\'])\n            if not old or old[\'status\']!=x[\'status\'] or old[\'source\']!=SOURCE or old[\'settled_at\']!=stamp or old[\'profit\']!=x[\'profit\'] or old[\'result_home\']!=x[\'hs\'] or old[\'result_away\']!=x[\'as\']:\n                raise RuntimeError(\'ROLLBACK_REFUSED_ROW_CHANGED:\'+sha8(x[\'forecast_id\']))\n        for x in ledger:\n            original=x[\'original\'];values=[original[col] for col in SCORE_COLS]+[x[\'forecast_id\']]\n            q=\'UPDATE v55_paper SET \'+\',\'.join(f\'{col}=?\' for col in SCORE_COLS)+\' WHERE forecast_id=?\'\n            if c.execute(q,values).rowcount!=1:raise RuntimeError(\'ROLLBACK_NON_ATOMIC_ROW_COUNT\')\n        c.execute(\'\'\'INSERT INTO v55_settlement_runs(checked_at,checked,settled,outcomes_unavailable,report)\n            VALUES(?,?,?,?,?)\'\'\',(timestamp(),len(ledger),0,len(ledger),json.dumps({\'state\':\'EVA_R10_REVERSAL\',\'tag\':data[\'tag\']})))\n        c.execute(\'COMMIT\')\n    except Exception:\n        if c.in_transaction:c.execute(\'ROLLBACK\')\n        raise\n    finally:c.close()\n    data[\'state\']=\'ROLLED_BACK\';atomic_json(path,data)\n    emit(\'EVA_R10_ROLLBACK_VERIFIED\',{\'rows_restored\':len(ledger),\'backup_retained\':data[\'backup\'],\'real_orders\':0})\n\n\ndef main():\n    action=os.environ.get(\'EVA_R10_ACTION\',\'apply\')\n    if action not in (\'apply\',\'audit\',\'rollback\'):raise RuntimeError(\'R9_ACTION_NOT_ALLOWED\')\n    # R8\'s independently reviewed target verifier is reused, but R9\'s\n    # own manifest and rollback cannot undo a prior R8 installation.\n    os.environ[\'EVA_RUN_MODE\']=\'rollback\' if action==\'rollback\' else \'apply\'\n    r8.validate_target()\n    if action==\'rollback\':rollback();return\n    ro=sqlite3.connect(f\'file:{DB}?mode=ro\',uri=True,timeout=30)\n    ro.execute(\'PRAGMA query_only=ON\')\n    try:report,ledger=census(ro)\n    finally:ro.close()\n    REPORTS.mkdir(parents=True,exist_ok=True,mode=0o700)\n    path=REPORTS/(f\'eva_r10_census_{now_utc():%Y%m%dT%H%M%SZ}_{uuid.uuid4().hex[:8]}.json\')\n    atomic_json(path,report)\n    emit(\'EVA_R10_CENSUS_REPORT_SAVED\',{\'path\':str(path),\'rows\':report[\'pending_total\'],\n                                      \'preview_candidate_count\':len(ledger)})\n    changed=write_settlement(ledger,report,action)\n    after=sqlite3.connect(f\'file:{DB}?mode=ro\',uri=True,timeout=30)\n    try:post_pnl=settled_pnl_snapshot(after)\n    finally:after.close()\n    emit(\'EVA_R10_FINAL_PAPER_PNL\',post_pnl)\n    emit(\'EVA_R10_COMPLETED\',{\'mode\':action,\'census\':report[\'pending_total\'],\'newly_settled\':changed,\n         \'unresolved_in_initial_census\':report[\'pending_total\']-changed-report[\'future_count\'],\n         \'report\':str(path),\'real_orders\':0})\n\n\nif __name__==\'__main__\':\n    try:main()\n    except Exception as ex:\n        emit(\'EVA_R10_ABORTED\',{\'reason\':type(ex).__name__+\': \'+str(ex)[:350],\n                              \'no_retry_without_checking_manifest\':True})\n        sys.exit(1)\n', 'engine.py', 'exec'), context)
